//! Generator of `spec/vectors/v1/*.json` (spec §11).
//!
//! The published vectors are FROZEN. This tool never overwrites a file: an existing file
//! must be regenerated byte for byte (otherwise it stops with an error), a missing file
//! is created, and `SHA256SUMS` may only gain lines. It documents how each value was
//! produced and checks that the code still produces the frozen bytes.
//!
//! Usage: `cargo run -p tomi-core --example gen_spec_vectors -- <output dir>`

use std::error::Error;
use std::fs;
use std::path::{Path, PathBuf};

use base64::engine::general_purpose::STANDARD as B64;
use base64::Engine as _;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use tomi_core::kat;
use tomi_core::{
    history_transfer_len, ArchiveBook, ArchiveState, ArchiveStatement, DeletionScope, DeviceKeys,
    DevicePublic, HistoryDevice, HistoryEntry, HistoryHeader, HistoryIndexReader,
    HistoryIndexWriter, HistoryItem, HistoryKey, HistoryPart, HistoryPartDecryptor,
    HistoryTransfer, ItemStateKind, PinBook, PinState, PinStatement, ReceivedItemState, SpaceKey,
    SpaceKeyRing, TransferredFile, TrustStore, UnreadableReason, ARCHIVE_STATEMENT_LEN,
    ATTACHMENT_TOMBSTONE_AT_MS_MAX, ATTACHMENT_TOMBSTONE_LEN, CHUNK_CIPHERTEXT_SIZE, CHUNK_SIZE,
    FORMAT_MAX, ITEM_STATE_ENVELOPE_LEN, PIN_STATEMENT_LEN,
};

type R<T> = Result<T, Box<dyn Error>>;

const SPACE_ID: &str = "5e1f0c2a-7b3d-4e8f-9a61-0c2d4e6f8a10";
const T0: i64 = 1_793_750_400_000; // 2026-11-04T00:00:00Z
const FROZEN_NOTE: &str =
    "FROZEN as of publication — never modify this file (spec/vectors/v1/README.md).";

fn h(b: &[u8]) -> String {
    hex::encode(b)
}

fn seq(start: u8, len: usize) -> Vec<u8> {
    (0..len).map(|i| start.wrapping_add(i as u8)).collect()
}

fn sha(b: &[u8]) -> String {
    h(&Sha256::digest(b))
}

fn file_bytes(len: usize) -> Vec<u8> {
    (0..len).map(|j| (j % 251) as u8).collect()
}

fn check(cond: bool, what: &str) -> R<()> {
    if cond {
        Ok(())
    } else {
        Err(format!("self-check failed: {what}").into())
    }
}

struct Dev {
    name: &'static str,
    ed_seed: Vec<u8>,
    x_secret: Vec<u8>,
    keys: DeviceKeys,
}

impl Dev {
    fn new(name: &'static str, ed: u8, x: u8) -> R<Self> {
        let ed_seed = seq(ed, 32);
        let x_secret = seq(x, 32);
        let keys = DeviceKeys::from_secrets(&ed_seed, &x_secret)?;
        Ok(Self {
            name,
            ed_seed,
            x_secret,
            keys,
        })
    }
    fn public(&self) -> DevicePublic {
        self.keys.public()
    }
    fn to_value(&self) -> Value {
        let p = self.public();
        json!({
            "name": self.name,
            "ed25519_seed": h(&self.ed_seed),
            "x25519_secret": h(&self.x_secret),
            "ed25519_public": h(&p.ed25519),
            "x25519_public": h(&p.x25519),
            "device_id": self.keys.device_id(),
        })
    }
}

fn devices() -> R<(Dev, Dev, Dev, Dev)> {
    Ok((
        Dev::new("A", 0xa0, 0x10)?,
        Dev::new("B", 0xc0, 0x30)?,
        Dev::new("C", 0xe0, 0x50)?,
        Dev::new("D", 0x11, 0x71)?,
    ))
}

/// Creates `name`, or checks that the existing frozen file has exactly these bytes.
fn write_frozen(path: &Path, bytes: &[u8]) -> R<()> {
    if path.exists() {
        let existing = fs::read(path)?;
        if existing != bytes {
            return Err(format!(
                "{} differs from the regenerated vector: vectors are frozen",
                path.display()
            )
            .into());
        }
        println!("unchanged {}", path.display());
        return Ok(());
    }
    fs::write(path, bytes)?;
    println!("wrote {}", path.display());
    Ok(())
}

fn write(dir: &Path, name: &str, v: &Value) -> R<()> {
    let mut s = serde_json::to_string_pretty(v)?;
    s.push('\n');
    write_frozen(&dir.join(name), s.as_bytes())
}

/// Builds one envelope vector with all intermediate values.
// One argument per vector input keeps the call sites readable next to the spec.
#[allow(clippy::too_many_arguments)]
fn envelope_vector(
    name: &str,
    description: &str,
    space_key: &SpaceKey,
    item_id: &str,
    cek: &[u8],
    wrap_nonce: &[u8],
    payload_nonce: &[u8],
    json_payload: &str,
) -> R<Value> {
    let epoch = space_key.epoch();
    let kw = kat::cek_wrap_key(space_key)?;
    let aad_w = kat::aad_cek_wrap(FORMAT_MAX, epoch, item_id)?;
    let aad_p = kat::aad_payload(FORMAT_MAX, epoch, item_id)?;
    let padded = kat::pad_payload(json_payload.as_bytes());
    let wrapped = kat::xchacha20poly1305_seal(&kw, wrap_nonce, &aad_w, cek)?;
    let ct = kat::xchacha20poly1305_seal(cek, payload_nonce, &aad_p, &padded)?;
    let env = kat::seal_envelope(
        space_key,
        item_id,
        cek,
        wrap_nonce,
        payload_nonce,
        json_payload.as_bytes(),
    )?;
    let mut manual = Vec::new();
    manual.extend_from_slice(&FORMAT_MAX.to_be_bytes());
    manual.extend_from_slice(&epoch.to_be_bytes());
    manual.extend_from_slice(uuid::Uuid::parse_str(item_id)?.as_bytes());
    manual.extend_from_slice(wrap_nonce);
    manual.extend_from_slice(&wrapped);
    manual.extend_from_slice(payload_nonce);
    manual.extend_from_slice(&ct);
    check(manual == env, "envelope layout")?;
    let opened = tomi_core::open_item(&env, item_id, space_key)?;
    Ok(json!({
        "name": name,
        "description": description,
        "format": FORMAT_MAX,
        "space_key": h(&space_key.to_bytes()),
        "key_epoch": epoch,
        "item_id": item_id,
        "cek": h(cek),
        "wrap_nonce": h(wrap_nonce),
        "payload_nonce": h(payload_nonce),
        "payload_json": json_payload,
        "payload_json_hex": h(json_payload.as_bytes()),
        "padded_payload": h(&padded),
        "cek_wrap_key": h(&kw),
        "aad_cek_wrap": h(&aad_w),
        "aad_payload": h(&aad_p),
        "wrapped_cek": h(&wrapped),
        "payload_ciphertext": h(&ct),
        "envelope": h(&env),
        "expected_item": kat::item_to_value(&opened.item),
    }))
}

fn primitives() -> R<Value> {
    // draft-irtf-cfrg-xchacha-03 §A.3.1
    let key = hex::decode("808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f")?;
    let nonce = hex::decode("404142434445464748494a4b4c4d4e4f5051525354555657")?;
    let aad = hex::decode("50515253c0c1c2c3c4c5c6c7")?;
    let pt = hex::decode("4c616469657320616e642047656e746c656d656e206f662074686520636c617373206f66202739393a204966204920636f756c64206f6666657220796f75206f6e6c79206f6e652074697020666f7220746865206675747572652c2073756e73637265656e20776f756c642062652069742e")?;
    let expected_ct = "bd6d179d3e83d43b9576579493c0e939572a1700252bfaccbed2902c21396cbb731c7f1b0b4aa6440bf3a82f4eda7e39ae64c6708c54c216cb96b72e1213b4522f8c9ba40db5d945b11b69b982c1bb9e3f3fac2bc369488f76b2383565d3fff921f9664c97637da9768812f615c68b13b52ec0875924c1c7987947deafd8780acf49";
    let ct = kat::xchacha20poly1305_seal(&key, &nonce, &aad, &pt)?;
    check(h(&ct) == expected_ct, "xchacha draft vector")?;

    // RFC 5869 A.1
    let okm = kat::hkdf_sha256(
        &hex::decode("000102030405060708090a0b0c")?,
        &[0x0b; 22],
        &hex::decode("f0f1f2f3f4f5f6f7f8f9")?,
        42,
    )?;
    check(
        h(&okm)
            == "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865",
        "rfc5869 a.1",
    )?;
    // RFC 5869 A.3 (empty salt and info)
    let okm3 = kat::hkdf_sha256(&[], &[0x0b; 22], &[], 42)?;
    check(
        h(&okm3)
            == "8da4e775a563c18f715f802a063c5a31b8a11f5c5ee1879ec3454e5f3c738d2d9d201395faa4b61a96c8",
        "rfc5869 a.3",
    )?;

    // RFC 7748 §6.1
    let a_sk = "77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a";
    let b_sk = "5dab087e624a8a4b79e17f8b83800ee66f3bb1292618b6fd1c2f8b27ff88e0eb";
    let a_pk = kat::x25519_public(&hex::decode(a_sk)?)?;
    let b_pk = kat::x25519_public(&hex::decode(b_sk)?)?;
    let shared = kat::x25519_shared(&hex::decode(a_sk)?, &b_pk)?;
    check(
        h(&a_pk) == "8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a",
        "x25519 alice",
    )?;
    check(
        h(&b_pk) == "de9edb7d7b7dc1b4d35b61c2ece435373f8343c85b78674dadfc7e146f882b4f",
        "x25519 bob",
    )?;
    check(
        h(&shared) == "4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742",
        "x25519 shared",
    )?;

    // RFC 8032 §7.1 tests 1 and 2
    let ed = [
        (
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
            "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
            "",
            "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b",
        ),
        (
            "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
            "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c",
            "72",
            "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00",
        ),
    ];
    let mut ed_vectors = Vec::new();
    for (i, (seed, public, msg, sig)) in ed.iter().enumerate() {
        let keys = DeviceKeys::from_secrets(&hex::decode(seed)?, &[0u8; 32])?;
        check(h(&keys.public().ed25519) == *public, "ed25519 public")?;
        let s = kat::ed25519_sign(&hex::decode(seed)?, &hex::decode(msg)?)?;
        check(h(&s) == *sig, "ed25519 signature")?;
        ed_vectors.push(json!({
            "source": format!("RFC 8032 §7.1 TEST {}", i + 1),
            "seed": seed, "public": public, "message": msg, "signature": sig,
        }));
    }

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "External test vectors for the primitives (RFC / IETF draft), to validate the choice of libraries. All values in hexadecimal.",
        "xchacha20poly1305": [{
            "source": "draft-irtf-cfrg-xchacha-03 §A.3.1",
            "key": h(&key), "nonce": h(&nonce), "aad": h(&aad), "plaintext": h(&pt),
            "ciphertext_and_tag": expected_ct,
        }],
        "hkdf_sha256": [
            {"source": "RFC 5869 A.1", "ikm": h(&[0x0b; 22]), "salt": "000102030405060708090a0b0c",
             "info": "f0f1f2f3f4f5f6f7f8f9", "length": 42, "okm": h(&okm)},
            {"source": "RFC 5869 A.3 (empty salt and info)", "ikm": h(&[0x0b; 22]), "salt": "",
             "info": "", "length": 42, "okm": h(&okm3)},
        ],
        "x25519": [{
            "source": "RFC 7748 §6.1",
            "alice_secret": a_sk, "alice_public": h(&a_pk),
            "bob_secret": b_sk, "bob_public": h(&b_pk), "shared": h(&shared),
        }],
        "ed25519": ed_vectors,
    }))
}

fn main() -> R<()> {
    let dir: PathBuf = std::env::args()
        .nth(1)
        .ok_or("usage: gen_spec_vectors <output dir>")?
        .into();
    fs::create_dir_all(&dir)?;
    let (a, b, c, d) = devices()?;
    let k1 = SpaceKey::from_bytes(1, &seq(0x00, 32))?;
    let k2_bytes = seq(0x70, 32);

    // ---------------------------------------------------------------- primitives
    write(&dir, "primitives.json", &primitives()?)?;

    // ---------------------------------------------------------------- hkdf
    let eph_pair = vec![0x77u8; 32];
    let eph_pub = kat::x25519_public(&eph_pair)?;
    let bx = b.public().x25519;
    let shared_b = kat::x25519_shared(&eph_pair, &bx)?;
    let tk = kat::transport_key(&shared_b, &eph_pub, &bx)?;
    let mut salt = eph_pub.clone();
    salt.extend_from_slice(&bx);
    check(
        kat::hkdf_sha256(&salt, &shared_b, b"tomi/v1/hkdf/key-transport", 32)? == tk,
        "transport hkdf",
    )?;
    let k2 = SpaceKey::from_bytes(2, &k2_bytes)?;
    write(
        &dir,
        "hkdf.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "HKDF-SHA256 derivations of the spec (§4). Empty salt = absent (32 zero bytes). Output length 32.",
            "cek_wrap": [
                {"space_key": h(&k1.to_bytes()), "salt": "", "info_ascii": "tomi/v1/hkdf/cek-wrap",
                 "info": h(b"tomi/v1/hkdf/cek-wrap"), "okm": h(&kat::cek_wrap_key(&k1)?)},
                {"space_key": h(&k2.to_bytes()), "salt": "", "info_ascii": "tomi/v1/hkdf/cek-wrap",
                 "info": h(b"tomi/v1/hkdf/cek-wrap"), "okm": h(&kat::cek_wrap_key(&k2)?)},
            ],
            "key_transport": [{
                "ephemeral_secret": h(&eph_pair), "ephemeral_public": h(&eph_pub),
                "recipient_x25519_secret": h(&b.x_secret), "recipient_x25519_public": h(&bx),
                "shared_secret": h(&shared_b),
                "salt": h(&salt), "info_ascii": "tomi/v1/hkdf/key-transport",
                "info": h(b"tomi/v1/hkdf/key-transport"), "okm": h(&tk),
            }],
        }),
    )?;

    // ---------------------------------------------------------------- aad
    let id_text = "0e7b5a3c-1d2f-4a6b-8c9d-0e1f2a3b4c5d";
    let id_att = "3c3d3e3f-4041-4243-8445-464748494a4b";
    write(
        &dir,
        "aad.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Canonical encoding of the AADs (§5.1, §6.3, §7.3). The item_id and the space_id are encoded as 16 raw bytes (RFC 9562), integers in big-endian.",
            "vectors": [
                {"kind": "cek_wrap", "format": 1, "key_epoch": 1, "item_id": id_text,
                 "aad": h(&kat::aad_cek_wrap(1, 1, id_text)?)},
                {"kind": "payload", "format": 1, "key_epoch": 1, "item_id": id_text,
                 "aad": h(&kat::aad_payload(1, 1, id_text)?)},
                {"kind": "payload", "format": 1, "key_epoch": 258, "item_id": id_text,
                 "aad": h(&kat::aad_payload(1, 258, id_text)?)},
                {"kind": "chunk", "format": 1, "item_id": id_att, "attachment_index": 2,
                 "aad": h(&kat::aad_chunk(1, id_att, 2)?)},
                {"kind": "key_transport", "space_id": SPACE_ID, "key_epoch": 2,
                 "recipient_ed25519": h(&b.public().ed25519),
                 "aad": h(&kat::aad_key_transport(SPACE_ID, 2, &b.public().ed25519)?)},
            ],
        }),
    )?;

    // ---------------------------------------------------------------- items (text)
    let a_id = a.keys.device_id();
    let id_secret = "1f2e3d4c-5b6a-4978-8695-a4b3c2d1e0f9";
    let id_rich = "2a2b2c2d-2e2f-4031-8233-343536373839";
    let json_text = format!(
        r#"{{"id":"{id_text}","source_device":"{a_id}","created_at":{T0},"expires_at":{},"read_policy":"until_expiry","secret":false,"text":{{"plain":"Bonjour depuis PC-Bureau","source_format":"plain"}}}}"#,
        T0 + 7 * 86_400_000
    );
    let json_secret = format!(
        r#"{{"id":"{id_secret}","source_device":"{a_id}","created_at":{T0},"expires_at":{},"read_policy":"after_first_read","secret":true,"text":{{"plain":"hunter2-Ünïcødé-🔑"}}}}"#,
        T0 + 3_600_000
    );
    let json_rich = format!(
        r#"{{"id":"{id_rich}","source_device":"{a_id}","created_at":{T0},"title":"Article intéressant","url":"https://example.org/a?b=1&c=é","text":{{"plain":"Article intéressant https://example.org/a?b=1&c=é","html":"<p>Article <a href=\"https://example.org/a?b=1&amp;c=%C3%A9\">intéressant</a></p>\n<ul><li>un</li><li>deux</li></ul>","markdown":"Article [intéressant](https://example.org/a?b=1&c=%C3%A9)\n\n- un\n- deux","source_format":"html"}}}}"#
    );
    let v_text = envelope_vector(
        "text_simple",
        "Item texte simple, non secret, expiration 7 jours.",
        &k1,
        id_text,
        &seq(0x20, 32),
        &seq(0x60, 24),
        &seq(0x80, 24),
        &json_text,
    )?;
    let v_secret = envelope_vector(
        "text_secret_unicode",
        "Secret (password) with non-ASCII characters and an emoji, single read, 1 h expiry; source_format absent -> plain.",
        &k1,
        id_secret,
        &seq(0x21, 32),
        &seq(0x61, 24),
        &seq(0x81, 24),
        &json_secret,
    )?;
    let v_rich = envelope_vector(
        "composite_link_html",
        "Composite item: title + URL + text in three representations (plain/html/markdown); payload > 256 bytes (two padding blocks). Epoch 2 key.",
        &k2,
        id_rich,
        &seq(0x22, 32),
        &seq(0x62, 24),
        &seq(0x82, 24),
        &json_rich,
    )?;
    write(
        &dir,
        "item-text.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Complete envelopes (§5): inputs (space key, CEK, nonces, JSON) and all intermediate values. A reader must obtain expected_item by decrypting envelope; a writer must produce envelope from the inputs.",
            "vectors": [v_text, v_secret, v_rich],
        }),
    )?;

    // ---------------------------------------------------------------- attachments
    let specs: [(&str, &str, &str, usize); 3] = [
        (
            "a0000000-0000-4000-8000-000000000000",
            "vide.txt",
            "text/plain",
            0,
        ),
        (
            "a1000000-0000-4000-8000-000000000001",
            "bloc.bin",
            "application/octet-stream",
            CHUNK_SIZE,
        ),
        (
            "a2000000-0000-4000-8000-000000000002",
            "photo.jpg",
            "image/jpeg",
            CHUNK_SIZE + 1000,
        ),
    ];
    let thumb = hex::decode("89504e470d0a1a0a")?;
    let mut att_vectors = Vec::new();
    let mut att_json = Vec::new();
    let mut blobs = Vec::new();
    for (k, (blob_id, name, mime, size)) in specs.iter().enumerate() {
        let idx = k as u32;
        let key = seq(0xc8u8.wrapping_add(8 * k as u8), 32);
        let prefix = seq(0x33 + 5 * k as u8, 19);
        let data = file_bytes(*size);
        let enc = kat::chunk_encryptor(id_att, idx, &key, &prefix)?;
        let mut blob = Vec::new();
        for part in data.chunks(10_000) {
            blob.extend(enc.update(part)?);
        }
        let fin = enc.finalize()?;
        blob.extend(&fin.ciphertext);
        check(
            blob.len() as u64 == tomi_core::encrypted_attachment_len(*size as u64),
            "blob len",
        )?;
        let n = if *size == 0 {
            1
        } else {
            size.div_ceil(CHUNK_SIZE)
        };
        let mut chunks = Vec::new();
        let mut manual = Vec::new();
        for i in 0..n {
            let start = i * CHUNK_SIZE;
            let end = (start + CHUNK_SIZE).min(*size);
            let last = i == n - 1;
            let ct = kat::encrypt_chunk(
                &key,
                &prefix,
                id_att,
                idx,
                i as u32,
                last,
                &data[start..end],
            )?;
            chunks.push(json!({
                "counter": i, "last": last,
                "nonce": h(&kat::chunk_nonce(&prefix, i as u32, last)?),
                "plaintext_offset": start, "plaintext_len": end - start,
                "ciphertext_offset": i * CHUNK_CIPHERTEXT_SIZE, "ciphertext_len": ct.len(),
                "ciphertext_sha256": sha(&ct),
            }));
            manual.extend(ct);
        }
        check(manual == blob, "chunk layout")?;
        let thumb_json = if k == 2 {
            format!(
                r#","thumbnail":{{"mime":"image/png","data":"{}"}}"#,
                B64.encode(&thumb)
            )
        } else {
            String::new()
        };
        att_json.push(format!(
            r#"{{"blob_id":"{blob_id}","name":"{name}","mime":"{mime}","size":{size},"key":"{}","nonce_prefix":"{}"{thumb_json}}}"#,
            B64.encode(&key),
            B64.encode(&prefix)
        ));
        att_vectors.push(json!({
            "attachment_index": idx,
            "blob_id": blob_id,
            "size": size,
            "file_key": h(&key),
            "nonce_prefix": h(&prefix),
            "plaintext_rule": "octet j = j mod 251 (j = 0..size-1)",
            "plaintext_sha256": sha(&data),
            "aad_chunk": h(&kat::aad_chunk(1, id_att, idx)?),
            "chunks": chunks,
            "blob_len": blob.len(),
            "blob_sha256": sha(&blob),
            "blob": h(&blob),
        }));
        blobs.push(blob);
    }
    let json_att = format!(
        r#"{{"id":"{id_att}","source_device":"{a_id}","created_at":{T0},"expires_at":{},"title":"3 fichiers","attachments":[{}]}}"#,
        T0 + 86_400_000,
        att_json.join(",")
    );
    let v_att = envelope_vector(
        "attachments_multi_chunk",
        "Item with three attachments: empty file (1 final empty chunk), exactly 64 KiB (1 final full chunk), 64 KiB + 1000 bytes (2 chunks) with a thumbnail.",
        &k1,
        id_att,
        &seq(0x23, 32),
        &seq(0x63, 24),
        &seq(0x83, 24),
        &json_att,
    )?;
    write(
        &dir,
        "item-attachment.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "STREAM attachments (§6). The envelope references the blobs; each blob is the concatenation of the encrypted chunks.",
            "item": v_att,
            "attachments": att_vectors,
        }),
    )?;

    // ---------------------------------------------------------------- devices
    let issued = T0 as u64;
    let cert = a.keys.sign_device_cert(SPACE_ID, &c.public(), issued)?;
    let mut store_a = TrustStore::new(SPACE_ID, &a.public(), 1)?;
    store_a.add_verified_peer(&b.public())?;
    store_a.add_verified_peer(&c.public())?;
    let list = store_a.issue_member_list(&a.keys, issued + 1000)?;
    let nonce_seal = seq(0x90, 24);
    let sealed = kat::seal_space_key(&b.public(), SPACE_ID, &k1, &eph_pair, &nonce_seal)?;
    check(
        b.keys.open_space_key(SPACE_ID, 1, &sealed)?.to_bytes() == k1.to_bytes(),
        "open sealed",
    )?;
    let aad_t = kat::aad_key_transport(SPACE_ID, 1, &b.public().ed25519)?;
    write(
        &dir,
        "device.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Device identities (§7.1), device certificate (§8.2), member list (§8.2), space key transport (§7.3). D is not a member of the space.",
            "space_id": SPACE_ID,
            "devices": [a.to_value(), b.to_value(), c.to_value(), d.to_value()],
            "device_cert": {
                "description": "A certifie C.",
                "issuer": "A", "subject": "C", "issued_at_ms": issued,
                "signed_bytes": h(&cert.signed_bytes()?),
                "signature": h(&cert.signature),
                "wire": h(&cert.to_bytes()?),
            },
            "member_list": {
                "description": "List signed by A, epoch 1, members A, B, C sorted by Ed25519 key.",
                "issuer": "A", "key_epoch": 1, "issued_at_ms": issued + 1000,
                "members_order": list.members.iter().map(|m| {
                    [&a, &b, &c].iter().find(|d| d.public().ed25519 == m.ed25519).map(|d| d.name).unwrap_or("?")
                }).collect::<Vec<_>>(),
                "signed_bytes": h(&list.signed_bytes()?),
                "signature": h(&list.signature),
                "wire": h(&list.to_bytes()?),
            },
            "sealed_space_key": {
                "description": "Space key (epoch 1) sealed for B, as at pairing.",
                "recipient": "B", "space_key": h(&k1.to_bytes()), "key_epoch": 1,
                "ephemeral_secret": h(&eph_pair), "ephemeral_public": h(&eph_pub),
                "shared_secret": h(&shared_b), "transport_key": h(&tk),
                "nonce": h(&nonce_seal), "aad": h(&aad_t),
                "sealed": h(&sealed),
            },
        }),
    )?;

    // ---------------------------------------------------------------- tombstones
    let t1 = b.keys.sign_tombstone(
        SPACE_ID,
        id_text,
        issued + 3_600_000,
        DeletionScope::Everywhere,
    )?;
    let t2 = a
        .keys
        .sign_tombstone(SPACE_ID, id_secret, issued + 60_000, DeletionScope::Local)?;
    let tomb = |t: &tomi_core::Tombstone, signer: &str| -> R<Value> {
        Ok(json!({
            "signer": signer, "space_id": t.space_id, "item_id": t.item_id,
            "deleted_at_ms": t.deleted_at_ms,
            "scope": match t.scope { DeletionScope::Local => "local", DeletionScope::Everywhere => "everywhere" },
            "signed_bytes": h(&t.signed_bytes()?),
            "signature": h(&t.signature),
            "wire": h(&t.to_bytes()?),
        }))
    };
    write(
        &dir,
        "tombstone.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Ed25519-signed tombstones (§8.5). Devices in device.json. Scope: 0x01 local, 0x02 everywhere.",
            "vectors": [tomb(&t1, "B")?, tomb(&t2, "A")?],
        }),
    )?;

    // ---------------------------------------------------------------- rotation
    let mut recipients = [&a, &b];
    recipients.sort_by(|x, y| x.public().ed25519.cmp(&y.public().ed25519));
    let rand = [
        (vec![0x5au8; 32], seq(0x01, 24)),
        (vec![0xa5u8; 32], seq(0x41, 24)),
    ];
    let bundle = kat::create_rotation(
        &store_a,
        &a.keys,
        &[c.public().ed25519],
        issued + 7_200_000,
        SpaceKey::from_bytes(2, &k2_bytes)?,
        &rand,
    )?;
    let rot = &bundle.rotation;
    let mut rec_values = Vec::new();
    for (dev, (eph, nonce)) in recipients.iter().zip(rand.iter()) {
        let p = dev.public();
        let ephp = kat::x25519_public(eph)?;
        let sh = kat::x25519_shared(eph, &p.x25519)?;
        let entry = rot
            .recipients
            .iter()
            .find(|r| r.ed25519 == p.ed25519)
            .ok_or("missing recipient")?;
        rec_values.push(json!({
            "device": dev.name,
            "ed25519_public": h(&p.ed25519), "x25519_public": h(&p.x25519),
            "ephemeral_secret": h(eph), "ephemeral_public": h(&ephp), "nonce": h(nonce),
            "shared_secret": h(&sh),
            "transport_key": h(&kat::transport_key(&sh, &ephp, &p.x25519)?),
            "aad": h(&kat::aad_key_transport(SPACE_ID, 2, &p.ed25519)?),
            "sealed_key": h(&entry.sealed_key),
        }));
    }
    // Check expected outcomes.
    for (dev, revoked) in [(&a, false), (&b, false), (&c, true)] {
        let mut s = TrustStore::new(SPACE_ID, &dev.public(), 1)?;
        for o in [&a, &b, &c] {
            s.add_verified_peer(&o.public())?;
        }
        let out = s.apply_rotation(rot, &dev.keys)?;
        check(out.self_revoked == revoked, "rotation outcome")?;
        if let Some(k) = out.new_space_key {
            check(k.to_bytes() == k2_bytes, "rotation key")?;
        }
    }
    write(
        &dir,
        "rotation.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Space key rotation (§8.3): A revokes C, epoch 1 -> 2. Recipients sorted by ascending Ed25519 key; randomness supplied in that order. Devices in device.json.",
            "space_id": SPACE_ID,
            "trust_setup": {"key_epoch": 1, "members": ["A", "B", "C"]},
            "issuer": "A",
            "revoked": ["C"],
            "issued_at_ms": rot.issued_at_ms,
            "new_epoch": 2,
            "new_space_key": h(&k2_bytes),
            "recipients": rec_values,
            "signed_bytes": h(&rot.signed_bytes()?),
            "signature": h(&rot.signature),
            "wire": h(&rot.to_bytes()?),
            "expected": {
                "A": {"new_space_key": h(&k2_bytes)},
                "B": {"new_space_key": h(&k2_bytes)},
                "C": {"self_revoked": true},
            },
        }),
    )?;

    // ---------------------------------------------------------------- payload json
    let dev = &a_id;
    let pid = "4a4b4c4d-4e4f-4051-8253-545556575859";
    let pj = |name: &str, desc: &str, json_s: String, expected: Result<Value, &str>| -> R<Value> {
        let parsed = kat::parse_payload(json_s.as_bytes(), pid);
        match (&expected, &parsed) {
            (Ok(v), Ok(item)) => check(&kat::item_to_value(item) == v, name)?,
            (Err(code), Err(e)) => check(e.code() == *code, name)?,
            _ => return Err(format!("unexpected parse result for {name}").into()),
        }
        let mut v = json!({
            "name": name, "description": desc, "expected_item_id": pid,
            "json": json_s, "json_hex": h(json_s.as_bytes()),
        });
        match expected {
            Ok(item) => v["expected_item"] = item,
            Err(code) => v["expected_error"] = json!(code),
        }
        Ok(v)
    };
    let base = |extra: &str| {
        format!(r#"{{"id":"{pid}","source_device":"{dev}","created_at":{T0}{extra}}}"#)
    };
    let minimal_item = json!({
        "id": pid, "source_device": dev, "created_at_ms": T0, "expires_at_ms": null,
        "read_policy": "until_expiry", "secret": false, "title": null, "text": null,
        "url": null, "attachments": [],
    });
    let with = |patch: Value| {
        let mut v = minimal_item.clone();
        if let (Some(o), Some(p)) = (v.as_object_mut(), patch.as_object()) {
            for (k, val) in p {
                o.insert(k.clone(), val.clone());
            }
        }
        v
    };
    let mut cases = vec![
        pj(
            "minimal",
            "Mandatory fields only; defaults applied.",
            base(""),
            Ok(minimal_item.clone()),
        )?,
        pj(
            "unknown_fields_ignored",
            "Unknown fields at the root and in text: ignored without error (additive change).",
            base(r#","future_field":{"a":[1,2,{"b":null}]},"text":{"plain":"x","future":1}"#),
            Ok(with(
                json!({"text": {"plain": "x", "html": null, "markdown": null, "source_format": "plain"}}),
            )),
        )?,
        pj(
            "unknown_read_policy",
            "Unknown read_policy value -> after_first_read (the most restrictive).",
            base(r#","read_policy":"burn_after_reading""#),
            Ok(with(json!({"read_policy": "after_first_read"}))),
        )?,
        pj(
            "unknown_source_format",
            "Valeur de source_format inconnue -> plain.",
            base(r#","text":{"plain":"x","source_format":"asciidoc"}"#),
            Ok(with(
                json!({"text": {"plain": "x", "html": null, "markdown": null, "source_format": "plain"}}),
            )),
        )?,
        pj(
            "explicit_nulls",
            "Explicit null for optional fields = absent.",
            base(r#","expires_at":null,"title":null,"url":null,"text":null"#),
            Ok(minimal_item.clone()),
        )?,
        pj(
            "missing_id",
            "Champ obligatoire id absent.",
            format!(r#"{{"source_device":"{dev}","created_at":{T0}}}"#),
            Err("malformed_payload"),
        )?,
        pj(
            "missing_created_at",
            "Champ obligatoire created_at absent.",
            format!(r#"{{"id":"{pid}","source_device":"{dev}"}}"#),
            Err("malformed_payload"),
        )?,
        pj(
            "wrong_type",
            "created_at must be a JSON integer.",
            format!(r#"{{"id":"{pid}","source_device":"{dev}","created_at":"{T0}"}}"#),
            Err("malformed_payload"),
        )?,
        pj(
            "duplicate_field",
            "Duplicate JSON key: rejected.",
            base(r#","secret":false,"secret":true"#),
            Err("malformed_payload"),
        )?,
        pj(
            "id_mismatch",
            "Payload id differs from the envelope's item_id.",
            format!(
                r#"{{"id":"4a4b4c4d-4e4f-4051-8253-54555657585a","source_device":"{dev}","created_at":{T0}}}"#
            ),
            Err("item_id_mismatch"),
        )?,
        pj(
            "uppercase_uuid",
            "UUID non canonique (majuscules).",
            format!(
                r#"{{"id":"{}","source_device":"{dev}","created_at":{T0}}}"#,
                pid.to_uppercase()
            ),
            Err("malformed_payload"),
        )?,
        pj(
            "bad_source_device",
            "source_device must be 32 lowercase hexadecimal characters.",
            format!(
                r#"{{"id":"{pid}","source_device":"{}","created_at":{T0}}}"#,
                &dev[..31]
            ),
            Err("malformed_payload"),
        )?,
        pj(
            "text_without_plain",
            "text.plain is mandatory when text is present.",
            base(r#","text":{"html":"<b>x</b>"}"#),
            Err("malformed_payload"),
        )?,
        pj(
            "attachment_bad_key_len",
            "Attachment key: 31 bytes instead of 32.",
            base(&format!(
                r#","attachments":[{{"blob_id":"a0000000-0000-4000-8000-000000000000","name":"f","mime":"text/plain","size":1,"key":"{}","nonce_prefix":"{}"}}]"#,
                B64.encode([0u8; 31]),
                B64.encode([0u8; 19])
            )),
            Err("malformed_payload"),
        )?,
    ];
    // Invalid UTF-8 (only representable in hex).
    let bad_utf8 = {
        let mut bytes = base(r#","title":"X""#).into_bytes();
        let pos = bytes.iter().rposition(|&x| x == b'X').ok_or("X")?;
        bytes[pos] = 0xff;
        bytes
    };
    check(
        kat::parse_payload(&bad_utf8, pid).map_err(|e| e.code()) == Err("malformed_payload"),
        "bad utf8",
    )?;
    cases.push(json!({
        "name": "invalid_utf8", "description": "Byte 0xff inside a string: invalid JSON (UTF-8 is mandatory). Use json_hex.",
        "expected_item_id": pid, "json_hex": h(&bad_utf8), "expected_error": "malformed_payload",
    }));
    write(
        &dir,
        "payload-json.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Reading the payload JSON (§5.4) after decryption and padding removal. Read json_hex (exact bytes); json is the same thing as text when possible.",
            "vectors": cases,
        }),
    )?;

    // ---------------------------------------------------------------- failures
    let env_text = hex::decode(v_text["envelope"].as_str().ok_or("env")?)?;
    let alt_id = "0e7b5a3c-1d2f-4a6b-8c9d-0e1f2a3b4c5e";
    let mut env_cases = Vec::new();
    let mut env_case = |name: &str,
                        desc: &str,
                        env: Vec<u8>,
                        expected_id: &str,
                        key: &[u8],
                        epoch: u32,
                        code: &str|
     -> R<()> {
        let sk = SpaceKey::from_bytes(epoch, key)?;
        let got = tomi_core::open_item(&env, expected_id, &sk);
        check(got.as_ref().err().map(|e| e.code()) == Some(code), name)?;
        env_cases.push(json!({
            "name": name, "description": desc, "envelope": h(&env),
            "expected_item_id": expected_id, "space_key": h(key), "key_epoch": epoch,
            "expected_error": code,
        }));
        Ok(())
    };
    let k1b = k1.to_bytes();
    {
        let mut e = env_text.clone();
        e[8..24].copy_from_slice(uuid::Uuid::parse_str(alt_id)?.as_bytes());
        env_case(
            "aad_item_id_altered",
            "Header item_id replaced (the relay swaps blobs): the AAD no longer matches.",
            e,
            alt_id,
            &k1b,
            1,
            "decryption_failed",
        )?;
    }
    {
        let mut e = env_text.clone();
        e[4..8].copy_from_slice(&2u32.to_be_bytes());
        env_case("aad_epoch_altered", "Header key_epoch changed to 2, key with identical bytes announced as epoch 2: the AAD no longer matches.", e, id_text, &k1b, 2, "decryption_failed")?;
    }
    {
        let mut e = env_text.clone();
        e[0..4].copy_from_slice(&2u32.to_be_bytes());
        env_case("unknown_format_2", "format = 2, unknown to this reader: display \"unreadable, update the app\", never delete.", e, id_text, &k1b, 1, "unsupported_format")?;
    }
    {
        let mut e = env_text.clone();
        e[0..4].copy_from_slice(&0u32.to_be_bytes());
        env_case(
            "format_zero",
            "format = 0 does not exist.",
            e,
            id_text,
            &k1b,
            1,
            "unsupported_format",
        )?;
    }
    {
        let mut e = env_text.clone();
        let last = e.len() - 1;
        e[last] ^= 0x01;
        env_case(
            "payload_tag_bit_flip",
            "Last bit of the payload's Poly1305 tag flipped.",
            e,
            id_text,
            &k1b,
            1,
            "decryption_failed",
        )?;
    }
    {
        let mut e = env_text.clone();
        e[48] ^= 0x80;
        env_case(
            "wrapped_cek_bit_flip",
            "First byte of the encrypted CEK modified.",
            e,
            id_text,
            &k1b,
            1,
            "decryption_failed",
        )?;
    }
    env_case(
        "wrong_space_key",
        "Right epoch, wrong space key.",
        env_text.clone(),
        id_text,
        &[0xffu8; 32],
        1,
        "decryption_failed",
    )?;
    env_case(
        "expected_id_mismatch",
        "The relay announces an item_id other than the header's.",
        env_text.clone(),
        alt_id,
        &k1b,
        1,
        "item_id_mismatch",
    )?;
    env_case(
        "key_epoch_mismatch",
        "The supplied key is from a different epoch than the header.",
        env_text.clone(),
        id_text,
        &k1b,
        2,
        "key_epoch_mismatch",
    )?;
    env_case(
        "truncated_envelope",
        "Envelope truncated to 100 bytes.",
        env_text[..100].to_vec(),
        id_text,
        &k1b,
        1,
        "malformed_envelope",
    )?;
    {
        let json_other = json_text.replace(id_text, alt_id);
        let e = kat::seal_envelope(
            &k1,
            id_text,
            &seq(0x24, 32),
            &seq(0x64, 24),
            &seq(0x84, 24),
            json_other.as_bytes(),
        )?;
        env_case(
            "payload_id_differs",
            "Header and AAD are correct but the encrypted JSON carries a different id.",
            e,
            id_text,
            &k1b,
            1,
            "item_id_mismatch",
        )?;
    }

    // Stream failures, expressed as transformations of item-attachment.json blobs.
    let att2 = &att_vectors[2];
    let key2 = hex::decode(att2["file_key"].as_str().ok_or("k")?)?;
    let pre2 = hex::decode(att2["nonce_prefix"].as_str().ok_or("p")?)?;
    let tail = &file_bytes(CHUNK_SIZE + 1000)[CHUNK_SIZE..];
    let tail_not_last = kat::encrypt_chunk(&key2, &pre2, id_att, 2, 1, false, tail)?;
    let tail_counter0 = kat::encrypt_chunk(&key2, &pre2, id_att, 2, 0, true, tail)?;
    let stream_cases = vec![
        json!({"name": "truncated_last_chunk", "description": "Blob with its last chunk removed: finalization impossible.",
               "attachment_index": 2, "decrypt_with_index": 2,
               "transform": [{"op": "truncate", "len": CHUNK_CIPHERTEXT_SIZE}],
               "expected_error": "stream_truncated"}),
        json!({"name": "last_flag_missing", "description": "Last chunk re-encrypted with flag 0x00 (non-final): rejected.",
               "attachment_index": 2, "decrypt_with_index": 2,
               "transform": [{"op": "splice", "offset": CHUNK_CIPHERTEXT_SIZE, "data": h(&tail_not_last)}],
               "expected_error": "decryption_failed"}),
        json!({"name": "counter_mismatch", "description": "Last chunk re-encrypted with counter 0: reordering detected.",
               "attachment_index": 2, "decrypt_with_index": 2,
               "transform": [{"op": "splice", "offset": CHUNK_CIPHERTEXT_SIZE, "data": h(&tail_counter0)}],
               "expected_error": "decryption_failed"}),
        json!({"name": "trailing_data", "description": "One byte appended after the last chunk.",
               "attachment_index": 2, "decrypt_with_index": 2,
               "transform": [{"op": "append", "data": "00"}],
               "expected_error": "stream_trailing_data"}),
        json!({"name": "wrong_attachment_index", "description": "Blob of attachment 2 decrypted as attachment 1 (parameters of 2): different AAD.",
               "attachment_index": 2, "decrypt_with_index": 1, "transform": [],
               "expected_error": "decryption_failed"}),
    ];
    for case in &stream_cases {
        let mut blob = blobs[2].clone();
        for op in case["transform"].as_array().ok_or("ops")? {
            match op["op"].as_str() {
                Some("truncate") => blob.truncate(op["len"].as_u64().ok_or("len")? as usize),
                Some("append") => blob.extend(hex::decode(op["data"].as_str().ok_or("d")?)?),
                Some("splice") => {
                    let off = op["offset"].as_u64().ok_or("off")? as usize;
                    let data = hex::decode(op["data"].as_str().ok_or("d")?)?;
                    blob.truncate(off);
                    blob.extend(data);
                }
                _ => return Err("op".into()),
            }
        }
        let att = tomi_core::Attachment {
            blob_id: specs[2].0.into(),
            name: "x".into(),
            mime: "x".into(),
            size: (CHUNK_SIZE + 1000) as u64,
            file_key: key2.clone(),
            nonce_prefix: pre2.clone(),
            thumbnail: None,
        };
        let idx = case["decrypt_with_index"].as_u64().ok_or("idx")? as u32;
        let dec = tomi_core::ChunkDecryptor::new(id_att, idx, &att)?;
        let res = dec.update(&blob).and_then(|_| dec.finalize());
        check(
            res.err().map(|e| e.code()) == case["expected_error"].as_str(),
            "stream case",
        )?;
    }

    // Statement failures.
    let l_bytes = hex::decode("edd3f55c1a631258d69cf7a2def9de1400000000000000000000000000000010")?;
    let mut t1_wire = t1.to_bytes()?;
    let s_off = t1_wire.len() - 32;
    let mut carry = 0u16;
    for i in 0..32 {
        let v = t1_wire[s_off + i] as u16 + l_bytes[i] as u16 + carry;
        t1_wire[s_off + i] = (v & 0xff) as u8;
        carry = v >> 8;
    }
    check(carry == 0, "S+L fits")?;
    let mut t1_flip = t1.to_bytes()?;
    let last = t1_flip.len() - 1;
    t1_flip[last] ^= 0x01;
    let mut t1_scope = t1.to_bytes()?;
    t1_scope[21 + 1 + 16 + 16 + 8] = 0x01; // scope byte: everywhere -> local
    let td = d
        .keys
        .sign_tombstone(SPACE_ID, id_text, issued, DeletionScope::Everywhere)?;
    let mut cert_x = cert.to_bytes()?;
    cert_x[24 + 16 + 32] ^= 0x01; // first byte of subject x25519
    let self_cert = a.keys.sign_device_cert(SPACE_ID, &a.public(), issued)?;
    let mut rot_bad = rot.to_bytes()?;
    let pos = rot_bad.len() - 64 - 1; // last byte of the last sealed key
    rot_bad[pos] ^= 0x01;
    let mut store_a2 = TrustStore::new(SPACE_ID, &a.public(), 2)?;
    store_a2.add_verified_peer(&b.public())?;
    store_a2.add_verified_peer(&c.public())?;
    let rot3 = kat::create_rotation(
        &store_a2,
        &a.keys,
        &[],
        issued + 9_000_000,
        SpaceKey::from_bytes(3, &seq(0x90, 32))?,
        &[
            (vec![0x31; 32], seq(0x02, 24)),
            (vec![0x32; 32], seq(0x42, 24)),
            (vec![0x33; 32], seq(0x82, 24)),
        ],
    )?;
    let stmt_cases = vec![
        json!({"name": "tombstone_signature_bit_flip", "kind": "tombstone", "wire": h(&t1_flip),
               "trust_setup": {"self": "A", "key_epoch": 1, "members": ["A", "B", "C"]},
               "expected_error": "invalid_signature"}),
        json!({"name": "tombstone_scope_altered", "description": "Scope everywhere rewritten to local by the relay.",
               "kind": "tombstone", "wire": h(&t1_scope),
               "trust_setup": {"self": "A", "key_epoch": 1, "members": ["A", "B", "C"]},
               "expected_error": "invalid_signature"}),
        json!({"name": "tombstone_non_canonical_s", "description": "S replaced by S + L (same value modulo L): strict verification, rejected.",
               "kind": "tombstone", "wire": h(&t1_wire),
               "trust_setup": {"self": "A", "key_epoch": 1, "members": ["A", "B", "C"]},
               "expected_error": "invalid_signature"}),
        json!({"name": "tombstone_untrusted_signer", "description": "Valid signature by D, which is not a member.",
               "kind": "tombstone", "wire": h(&td.to_bytes()?),
               "trust_setup": {"self": "A", "key_epoch": 1, "members": ["A", "B", "C"]},
               "expected_error": "untrusted_signer"}),
        json!({"name": "device_cert_subject_altered", "description": "The relay substitutes the subject's X25519 key (D38).",
               "kind": "device_cert", "wire": h(&cert_x),
               "trust_setup": {"self": "B", "key_epoch": 1, "members": ["A", "B"]},
               "expected_error": "invalid_signature"}),
        json!({"name": "device_cert_self_signed", "description": "A self-signed certificate provides no trust.",
               "kind": "device_cert", "wire": h(&self_cert.to_bytes()?),
               "trust_setup": {"self": "B", "key_epoch": 1, "members": ["B"]},
               "expected_error": "untrusted_signer"}),
        json!({"name": "rotation_sealed_key_altered", "description": "One byte of a sealed key modified after signing.",
               "kind": "key_rotation", "wire": h(&rot_bad), "apply_as": "B",
               "trust_setup": {"self": "B", "key_epoch": 1, "members": ["A", "B", "C"]},
               "expected_error": "invalid_signature"}),
        json!({"name": "rotation_epoch_out_of_order", "description": "Valid rotation to epoch 3 presented to a device still on epoch 1.",
               "kind": "key_rotation", "wire": h(&rot3.rotation.to_bytes()?), "apply_as": "B",
               "trust_setup": {"self": "B", "key_epoch": 1, "members": ["A", "B", "C"]},
               "expected_error": "epoch_out_of_order"}),
        json!({"name": "rotation_untrusted_issuer", "description": "Valid rotation by A presented to D, which does not know A.",
               "kind": "key_rotation", "wire": h(&rot.to_bytes()?), "apply_as": "D",
               "trust_setup": {"self": "D", "key_epoch": 1, "members": ["D"]},
               "expected_error": "untrusted_signer"}),
    ];
    write(
        &dir,
        "failures.json",
        &json!({
            "frozen": FROZEN_NOTE,
            "description": "Expected failure cases. envelope: open the envelope with the given key and id. stream: start from the blob of item-attachment.json (attachment_index), apply transform in order (truncate = keep len bytes; splice = truncate at offset then append data; append = append data), decrypt with the parameters of attachment_index but the AAD of decrypt_with_index, then finalize. statements: build the TrustStore from trust_setup (self + verified peers, devices from device.json), then verify (tombstone, device_cert) or apply (key_rotation, with the keys of apply_as).",
            "envelope": env_cases,
            "stream": stream_cases,
            "statements": stmt_cases,
        }),
    )?;

    // ---------------------------------------------------------------- history transfer
    let mut att_item = tomi_core::open_item(
        &hex::decode(v_att["envelope"].as_str().ok_or("env")?)?,
        id_att,
        &k1,
    )?
    .item;
    // history-transfer.json was frozen with a payload serialized from the known fields (the
    // sender built this item). An opened item would export its original bytes instead
    // (spec §5.4.4, vectors `payload-extensions.json`); dropping them reproduces the frozen
    // index byte for byte.
    att_item.raw_payload = None;
    let hist = history_transfer(HistoryInputs {
        a: &a,
        b: &b,
        c: &c,
        d: &d,
        store_a: &store_a,
        rotation_wire: rot.to_bytes()?,
        att_item,
        id_att,
    })?;
    write(&dir, "history-transfer.json", &hist)?;

    // ---------------------------------------------------------------- pin (item state)
    let pins = pin_vectors(PinInputs {
        a: &a,
        b: &b,
        c: &c,
        d: &d,
        k1: &k1,
        k2: &k2,
        rotation_wire: rot.to_bytes()?,
        history_manifest: hex::decode(hist["manifest"]["wire"].as_str().ok_or("manifest")?)?,
        id_text,
    })?;
    write(&dir, "pin.json", &pins)?;

    // ---------------------------------------------------------------- archive (item state)
    let archives = archive_vectors(PinInputs {
        a: &a,
        b: &b,
        c: &c,
        d: &d,
        k1: &k1,
        k2: &k2,
        rotation_wire: rot.to_bytes()?,
        history_manifest: hex::decode(hist["manifest"]["wire"].as_str().ok_or("manifest")?)?,
        id_text,
    })?;
    write(&dir, "archive.json", &archives)?;

    // ---------------------------------------------------------------- attachment tombstone
    write(
        &dir,
        "attachment-tombstone.json",
        &attachment_tombstone_vectors(&a, &b, &c, &d, id_text, id_secret, issued)?,
    )?;

    // ---------------------------------------------------------------- reservations
    let reservations = reservation_vectors(&a, &b, &c, &k1, &k2)?;
    write(&dir, "reservations.json", &reservations)?;

    // ---------------------------------------------------------------- payload extensions
    write(
        &dir,
        "payload-extensions.json",
        &payload_extension_vectors(&a)?,
    )?;

    // ---------------------------------------------------------------- checksums
    let mut names: Vec<String> = fs::read_dir(&dir)?
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".json"))
        .collect();
    names.sort();
    let mut sums = String::new();
    for n in &names {
        let content = fs::read(dir.join(n))?;
        sums.push_str(&format!("{}  {}\n", sha(&content), n));
    }
    let sums_path = dir.join("SHA256SUMS");
    if sums_path.exists() {
        // Only additions are allowed: every published line must still be there.
        let existing = fs::read_to_string(&sums_path)?;
        for line in existing.lines().filter(|l| !l.trim().is_empty()) {
            if !sums.lines().any(|l| l == line) {
                return Err(format!("SHA256SUMS would lose or change `{line}`").into());
            }
        }
        if existing == sums {
            println!("unchanged SHA256SUMS");
        } else {
            fs::write(&sums_path, &sums)?;
            println!("added lines to SHA256SUMS");
        }
    } else {
        fs::write(&sums_path, &sums)?;
        println!("wrote SHA256SUMS");
    }
    Ok(())
}

// ---------------------------------------------------------------- history transfer

/// One JSON object per line of `index`, for the readable `expected_entries` field.
fn history_entry_value(e: &HistoryEntry) -> Value {
    match e {
        HistoryEntry::Device(d) => json!({
            "kind": "device", "device_id": d.device_id, "name": d.name,
            "platform": d.platform, "revoked": d.revoked,
        }),
        HistoryEntry::Item(i) => json!({
            "kind": "item",
            "item": kat::item_to_value(&i.item),
            "origin_seq": i.origin_seq,
            "received_at_ms": i.received_at_ms,
            "read": i.read,
            "kept": i.kept,
            "files": i.files.iter().map(|f| f.as_ref().map(|f| json!({
                "blob_id": f.blob_id,
                "file_key": h(&f.file_key),
                "nonce_prefix": h(&f.nonce_prefix),
            }))).collect::<Vec<_>>(),
        }),
    }
}

/// STREAM chunk table of a blob (nonces, lengths, digests).
fn chunk_table(blob: &[u8], prefix: &[u8], plaintext_len: usize) -> R<Vec<Value>> {
    let n = if plaintext_len == 0 {
        1
    } else {
        plaintext_len.div_ceil(CHUNK_SIZE)
    };
    let mut out = Vec::new();
    for i in 0..n {
        let last = i == n - 1;
        let start = i * CHUNK_CIPHERTEXT_SIZE;
        let end = if last {
            blob.len()
        } else {
            start + CHUNK_CIPHERTEXT_SIZE
        };
        out.push(json!({
            "counter": i, "last": last,
            "nonce": h(&kat::chunk_nonce(prefix, i as u32, last)?),
            "plaintext_offset": i * CHUNK_SIZE,
            "plaintext_len": (plaintext_len - i * CHUNK_SIZE).min(CHUNK_SIZE),
            "ciphertext_offset": start, "ciphertext_len": end - start,
            "ciphertext_sha256": sha(&blob[start..end]),
        }));
    }
    Ok(out)
}

struct HistoryInputs<'a> {
    a: &'a Dev,
    b: &'a Dev,
    c: &'a Dev,
    d: &'a Dev,
    store_a: &'a TrustStore,
    rotation_wire: Vec<u8>,
    att_item: tomi_core::Item,
    id_att: &'a str,
}

fn history_transfer(x: HistoryInputs<'_>) -> R<Value> {
    let HistoryInputs {
        a,
        b,
        c,
        d,
        store_a,
        rotation_wire,
        att_item,
        id_att,
    } = x;
    let transfer_id = "c1a7e0d2-5b3f-4e8a-9c61-2d4f6a8b0c1e";
    let as_of_seq: u64 = 1_793_754_000_123;
    let created_at = T0 as u64 + 10_800_000;
    let hk_bytes = seq(0xd0, 32);
    let hk = HistoryKey::from_bytes(&hk_bytes)?;
    let eph = vec![0x99u8; 32];
    let nonce = seq(0xb0, 24);
    let bp = b.public();
    let eph_pub = kat::x25519_public(&eph)?;
    let shared = kat::x25519_shared(&eph, &bp.x25519)?;
    let tk = kat::history_transport_key(&shared, &eph_pub, &bp.x25519)?;
    let mut salt = eph_pub.clone();
    salt.extend_from_slice(&bp.x25519);
    check(
        kat::hkdf_sha256(&salt, &shared, b"tomi/v1/hkdf/history-transport", 32)? == tk,
        "history transport hkdf",
    )?;
    let aad_t = kat::aad_history_transport(SPACE_ID, transfer_id, &bp.ed25519)?;

    // --- index lines
    let header = HistoryHeader {
        space_id: SPACE_ID.into(),
        transfer_id: transfer_id.into(),
        as_of_seq,
        source_device: a.keys.device_id(),
    };
    let mut long_text = String::new();
    let mut i = 0;
    while long_text.len() < 66_000 {
        long_text.push_str(&format!("Ligne {i:05} du compte rendu.\n"));
        i += 1;
    }
    let long_item = tomi_core::Item {
        id: "7a7b7c7d-7e7f-4081-8283-848586878889".into(),
        source_device: a.keys.device_id(),
        created_at_ms: T0 - 86_400_000,
        expires_at_ms: None,
        read_policy: tomi_core::ReadPolicy::UntilExpiry,
        secret: false,
        title: Some("Compte rendu".into()),
        text: Some(tomi_core::ItemText {
            plain: long_text,
            html: None,
            markdown: None,
            source_format: tomi_core::SourceFormat::Plain,
        }),
        url: None,
        attachments: vec![],
        raw_payload: None,
    };
    let secret_item = tomi_core::Item {
        id: "5c5d5e5f-6061-4263-8465-666768696a6b".into(),
        source_device: c.keys.device_id(),
        created_at_ms: T0 - 3_600_000,
        expires_at_ms: None,
        read_policy: tomi_core::ReadPolicy::UntilExpiry,
        secret: true,
        title: Some("Code Wi-Fi maison".into()),
        text: Some(tomi_core::ItemText {
            plain: "correct horse battery staple".into(),
            html: None,
            markdown: None,
            source_format: tomi_core::SourceFormat::Plain,
        }),
        url: None,
        attachments: vec![],
        raw_payload: None,
    };
    check(
        secret_item.visible_title().is_none() && secret_item.searchable_text().is_none(),
        "secret title masked",
    )?;

    // Re-encrypted files of the attachment item: 0 and 2 transferred, 1 unavailable.
    let file_specs: [(usize, &str, Vec<u8>, Vec<u8>); 2] = [
        (
            0,
            "f0000000-0000-4000-8000-000000000000",
            seq(0x05, 32),
            seq(0x15, 19),
        ),
        (
            2,
            "f2000000-0000-4000-8000-000000000002",
            seq(0x25, 32),
            seq(0x45, 19),
        ),
    ];
    let mut files: Vec<Option<TransferredFile>> = vec![None; att_item.attachments.len()];
    let mut file_values = Vec::new();
    for (idx, blob_id, key, prefix) in &file_specs {
        let size = att_item.attachments[*idx].size as usize;
        let data = file_bytes(size);
        let enc = kat::chunk_encryptor(id_att, *idx as u32, key, prefix)?;
        let mut blob = Vec::new();
        for part in data.chunks(10_000) {
            blob.extend(enc.update(part)?);
        }
        blob.extend(enc.finalize()?.ciphertext);
        let original = &att_item.attachments[*idx];
        check(
            original.file_key != *key && original.nonce_prefix != *prefix,
            "fresh file key",
        )?;
        files[*idx] = Some(TransferredFile {
            blob_id: (*blob_id).into(),
            file_key: key.clone(),
            nonce_prefix: prefix.clone(),
        });
        let mut v = json!({
            "item_id": id_att, "attachment_index": idx, "blob_id": blob_id,
            "size": size, "file_key": h(key), "nonce_prefix": h(prefix),
            "plaintext_rule": "octet j = j mod 251 (j = 0..size-1)",
            "plaintext_sha256": sha(&data),
            "aad_chunk": h(&kat::aad_chunk(1, id_att, *idx as u32)?),
            "chunks": chunk_table(&blob, prefix, size)?,
            "blob_len": blob.len(),
            "blob_sha256": sha(&blob),
        });
        if blob.len() <= 1024 {
            v["blob"] = json!(h(&blob));
        }
        file_values.push(v);
    }

    let devices = [
        HistoryDevice {
            device_id: a.keys.device_id(),
            name: "PC-Bureau".into(),
            platform: "windows".into(),
            revoked: false,
        },
        HistoryDevice {
            device_id: c.keys.device_id(),
            name: "Ancien téléphone".into(),
            platform: "android".into(),
            revoked: true,
        },
    ];
    let items = [
        HistoryItem {
            item: long_item,
            origin_seq: 1_793_664_000_017,
            received_at_ms: T0 - 86_400_000 + 900,
            read: true,
            kept: false,
            files: vec![],
            removed_attachments: vec![],
            pin: None,
            archive: None,
        },
        HistoryItem {
            item: att_item.clone(),
            origin_seq: 1_793_750_400_120,
            received_at_ms: T0 + 2_000,
            read: true,
            kept: true,
            files,
            removed_attachments: vec![],
            pin: None,
            archive: None,
        },
        HistoryItem {
            item: secret_item.clone(),
            origin_seq: 1_793_746_800_555,
            received_at_ms: T0 - 3_600_000 + 1_500,
            read: false,
            kept: false,
            files: vec![],
            removed_attachments: vec![],
            pin: None,
            archive: None,
        },
    ];
    let mut w = HistoryIndexWriter::new(&header)?;
    let mut part0 = w.header_line()?;
    for dv in &devices {
        part0.extend(w.device_line(dv)?);
    }
    part0.extend(w.item_line(&items[0])?);
    let mut part1 = w.item_line(&items[1])?;
    part1.extend(w.item_line(&items[2])?);
    part1.extend(w.end_line(1)?);
    let mut index = part0.clone();
    index.extend(&part1);
    let index_text = String::from_utf8(index.clone())?;
    check(part0.len() > CHUNK_SIZE, "part 0 spans two chunks")?;

    // --- encrypted parts
    let part_specs = [
        (
            "b0000000-0000-4000-8000-000000000000",
            seq(0x51, 19),
            &part0,
        ),
        (
            "b1000000-0000-4000-8000-000000000001",
            seq(0x65, 19),
            &part1,
        ),
    ];
    let mut parts = Vec::new();
    let mut part_values = Vec::new();
    let mut part_blobs = Vec::new();
    let mut offset = 0;
    for (p, (blob_id, prefix, plain)) in part_specs.iter().enumerate() {
        let enc = kat::history_part_encryptor(&hk, transfer_id, p as u32, 2, prefix)?;
        let mut blob = Vec::new();
        for piece in plain.chunks(7_000) {
            blob.extend(enc.update(piece)?);
        }
        blob.extend(enc.finalize()?);
        parts.push(HistoryPart {
            blob_id: (*blob_id).into(),
            nonce_prefix: prefix.clone(),
        });
        part_values.push(json!({
            "part_index": p, "blob_id": blob_id, "nonce_prefix": h(prefix),
            "aad": h(&kat::aad_history_chunk(1, transfer_id, p as u32, 2)?),
            "plaintext_offset": offset, "plaintext_len": plain.len(),
            "chunks": chunk_table(&blob, prefix, plain.len())?,
            "blob_len": blob.len(),
            "blob_sha256": sha(&blob),
            "blob": h(&blob),
        }));
        offset += plain.len();
        part_blobs.push(blob);
    }

    // --- manifest
    let m = kat::create_history_transfer(
        store_a,
        &a.keys,
        &bp.ed25519,
        transfer_id,
        as_of_seq,
        created_at,
        &hk,
        &parts,
        &eph,
        &nonce,
    )?;
    let wire = m.to_bytes()?;
    check(wire.len() == history_transfer_len(2), "manifest length")?;
    check(wire.len() == 383, "manifest length 383")?;
    let store = |me: &Dev, members: &[&Dev]| -> R<TrustStore> {
        let mut s = TrustStore::new(SPACE_ID, &me.public(), 1)?;
        for o in members {
            s.add_verified_peer(&o.public())?;
        }
        Ok(s)
    };
    let store_b = store(b, &[a, b, c])?;
    let opened = store_b.verify_history_transfer(&HistoryTransfer::from_bytes(&wire)?, &b.keys)?;
    check(opened.to_bytes() == hk_bytes, "history key opens")?;

    // Recipient side through the public API.
    let mut reader = HistoryIndexReader::new(&m)?;
    let mut entries = Vec::new();
    for (p, blob) in part_blobs.iter().enumerate() {
        let dec = HistoryPartDecryptor::new(&opened, &m, p as u32)?;
        entries.extend(reader.feed(&dec.update(blob)?)?);
        entries.extend(reader.feed(&dec.finalize()?)?);
    }
    let summary = reader.finish()?;
    check(
        summary.items == 3 && summary.files_unavailable == 1,
        "summary",
    )?;

    // --- failures
    let sign_with = |dev: &Dev, mut t: HistoryTransfer| -> R<Vec<u8>> {
        t.signature = kat::ed25519_sign(&dev.ed_seed, &t.signed_bytes()?)?;
        Ok(t.to_bytes()?)
    };
    let mut to_c = m.clone();
    to_c.recipient_ed25519 = c.public().ed25519;
    let wire_to_c = sign_with(a, to_c)?;
    let from_d = kat::create_history_transfer(
        &store(d, &[b])?,
        &d.keys,
        &bp.ed25519,
        transfer_id,
        as_of_seq,
        created_at,
        &hk,
        &parts,
        &eph,
        &nonce,
    )?
    .to_bytes()?;
    let from_c = kat::create_history_transfer(
        &store(c, &[a, b])?,
        &c.keys,
        &bp.ed25519,
        transfer_id,
        as_of_seq,
        created_at,
        &hk,
        &parts,
        &eph,
        &nonce,
    )?
    .to_bytes()?;
    let mut one_part = m.clone();
    one_part.parts.truncate(1);
    let wire_one_part = one_part.to_bytes()?;
    let setup = |me: &str, rot: bool| {
        let mut v = json!({"self": me, "key_epoch": 1, "members": ["A", "B", "C"]});
        if rot {
            v["apply_rotation"] = json!("rotation.json");
        }
        v
    };
    let manifest_cases = vec![
        json!({"name": "sealed_key_for_other_device", "description": "Manifest signed by A for C, but key sealed for B: C cannot open it.",
               "wire": h(&wire_to_c), "trust_setup": setup("C", false), "expected_error": "decryption_failed"}),
        json!({"name": "untrusted_signer", "description": "Valid manifest signed by D, which is not a member.",
               "wire": h(&from_d), "trust_setup": setup("B", false), "expected_error": "untrusted_signer"}),
        json!({"name": "revoked_signer", "description": "Valid manifest signed by C, presented to B after the rotation of rotation.json (C revoked).",
               "wire": h(&from_c), "trust_setup": setup("B", true), "expected_error": "revoked_device"}),
        json!({"name": "not_a_recipient", "description": "Manifest A -> B presented to C.",
               "wire": h(&wire), "trust_setup": setup("C", false), "expected_error": "not_a_recipient"}),
        json!({"name": "n_parts_altered", "description": "Second part removed and n_parts reduced to 1, original signature kept.",
               "wire": h(&wire_one_part), "trust_setup": setup("B", false), "expected_error": "invalid_signature"}),
    ];
    for case in &manifest_cases {
        let me = case["trust_setup"]["self"].as_str().ok_or("self")?;
        let dev = [a, b, c].into_iter().find(|x| x.name == me).ok_or("dev")?;
        let mut st = store(dev, &[a, b, c])?;
        if case["trust_setup"].get("apply_rotation").is_some() {
            st.apply_rotation(
                &tomi_core::KeyRotation::from_bytes(&rotation_wire)?,
                &dev.keys,
            )?;
        }
        let w = hex::decode(case["wire"].as_str().ok_or("wire")?)?;
        let got =
            HistoryTransfer::from_bytes(&w).and_then(|t| st.verify_history_transfer(&t, &dev.keys));
        check(
            got.err().map(|e| e.code()) == case["expected_error"].as_str(),
            case["name"].as_str().ok_or("name")?,
        )?;
    }
    let part_cases = vec![
        json!({"name": "parts_swapped", "description": "Blob of part 1 decrypted as part 0 (the relay swaps blobs): different AAD and nonce.",
               "blob_of_part": 1, "decrypt_as_part": 0, "transform": [], "expected_error": "decryption_failed"}),
        json!({"name": "part_last_chunk_removed", "description": "Part 0 with its last chunk removed: the remainder authenticates as a non-final chunk.",
               "blob_of_part": 0, "decrypt_as_part": 0,
               "transform": [{"op": "truncate", "len": CHUNK_CIPHERTEXT_SIZE}], "expected_error": "stream_truncated"}),
    ];
    for case in &part_cases {
        let mut blob = part_blobs[case["blob_of_part"].as_u64().ok_or("p")? as usize].clone();
        if let Some(op) = case["transform"].as_array().and_then(|a| a.first()) {
            blob.truncate(op["len"].as_u64().ok_or("len")? as usize);
        }
        let dec = HistoryPartDecryptor::new(
            &opened,
            &m,
            case["decrypt_as_part"].as_u64().ok_or("p")? as u32,
        )?;
        let got = dec.update(&blob).and_then(|_| dec.finalize());
        check(
            got.err().map(|e| e.code()) == case["expected_error"].as_str(),
            "part case",
        )?;
    }
    // Small indexes (header + the secret item) to check the reader rules.
    let small = |hdr: &HistoryHeader| -> R<(Vec<u8>, Vec<u8>, Vec<u8>)> {
        let mut w = HistoryIndexWriter::new(hdr)?;
        Ok((w.header_line()?, w.item_line(&items[2])?, w.end_line(0)?))
    };
    let (h_line, s_line, e_line) = small(&header)?;
    let mut other = header.clone();
    other.transfer_id = "c1a7e0d2-5b3f-4e8a-9c61-2d4f6a8b0c1f".into();
    let (h_other, _, _) = small(&other)?;
    let cat = |parts: &[&[u8]]| String::from_utf8(parts.concat());
    let end_two =
        b"{\"kind\":\"end\",\"items\":2,\"skipped\":{\"unreadable\":0,\"files_unavailable\":0}}\n";
    let future = b"{\"kind\":\"future\",\"x\":[1,{\"y\":null}]}\n";
    let index_cases = vec![
        json!({"name": "minimal_ok", "description": "Header, one secret, end.",
               "index": cat(&[&h_line, &s_line, &e_line])?, "expected_summary": {"items": 1, "skipped_unreadable": 0, "files_unavailable": 0}}),
        json!({"name": "unknown_kind_ignored", "description": "Line of an unknown kind: ignored (additive change).",
               "index": cat(&[&h_line, future, &s_line, &e_line])?, "expected_summary": {"items": 1, "skipped_unreadable": 0, "files_unavailable": 0}}),
        json!({"name": "end_missing", "description": "No end line.",
               "index": cat(&[&h_line, &s_line])?, "expected_error": "history_incomplete"}),
        json!({"name": "header_transfer_id_differs", "description": "header.transfer_id differs from the manifest's.",
               "index": cat(&[&h_other, &s_line, &e_line])?, "expected_error": "malformed_payload"}),
        json!({"name": "header_not_first", "description": "An item line before the header.",
               "index": cat(&[&s_line, &h_line, &e_line])?, "expected_error": "malformed_payload"}),
        json!({"name": "duplicate_item", "description": "The same item twice.",
               "index": cat(&[&h_line, &s_line, &s_line, end_two])?, "expected_error": "malformed_payload"}),
        json!({"name": "end_count_mismatch", "description": "end.items does not match the number of item lines.",
               "index": cat(&[&h_line, &s_line, end_two])?, "expected_error": "malformed_payload"}),
        json!({"name": "data_after_end", "description": "A line after end.",
               "index": cat(&[&h_line, &s_line, &e_line, future])?, "expected_error": "malformed_payload"}),
    ];
    for case in &index_cases {
        let mut r = HistoryIndexReader::new(&m)?;
        let text = case["index"].as_str().ok_or("index")?;
        let got = r.feed(text.as_bytes()).and_then(|_| r.finish());
        let ok = match (&got, case.get("expected_error")) {
            (Err(e), Some(code)) => Some(e.code()) == code.as_str(),
            (Ok(s), None) => s.items == case["expected_summary"]["items"].as_u64().ok_or("n")?,
            _ => false,
        };
        check(ok, case["name"].as_str().ok_or("name")?)?;
    }

    // D1 and secret titles, read as payloads.
    let pid = "6c6d6e6f-7071-4273-8475-767778797a7b";
    let c_id = c.keys.device_id();
    let payload_cases = [
        (
            "secret_without_expiry_or_policy",
            "Secret without expires_at or read_policy: never expires, until_expiry (D1). The title is part of the secret: no visible title, nothing indexable.",
            format!(r#"{{"id":"{pid}","source_device":"{c_id}","created_at":{T0},"secret":true,"title":"Code Wi-Fi maison","text":{{"plain":"correct horse battery staple"}}}}"#),
        ),
        (
            "plain_item_title_visible",
            "Non-secret item: the title is visible and indexable.",
            format!(r#"{{"id":"{pid}","source_device":"{c_id}","created_at":{T0},"title":"Liste de courses","text":{{"plain":"lait, œufs"}},"url":"https://example.org/"}}"#),
        ),
    ];
    let mut payload_values = Vec::new();
    for (name, desc, js) in &payload_cases {
        let it = kat::parse_payload(js.as_bytes(), pid)?;
        payload_values.push(json!({
            "name": name, "description": desc, "expected_item_id": pid,
            "json": js, "json_hex": h(js.as_bytes()),
            "expected_item": kat::item_to_value(&it),
            "expected_visible_title": it.visible_title(),
            "expected_searchable_text": it.searchable_text(),
        }));
    }

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Sealed history transfer (§7.4, §8.7, decision D2: the whole feed, secrets and files included, no partial option). A (PC-Bureau) transfers to B; C (old phone) is revoked by rotation.json; D is not a member. Devices in device.json. The \"randomness\" inputs are fixed for the tests.",
        "space_id": SPACE_ID,
        "transfer_id": transfer_id,
        "sender": "A",
        "recipient": "B",
        "trust_setup": {"key_epoch": 1, "members": ["A", "B", "C"]},
        "history_key": h(&hk_bytes),
        "sealed_key": {
            "ephemeral_secret": h(&eph), "ephemeral_public": h(&eph_pub),
            "recipient_x25519_public": h(&bp.x25519), "shared_secret": h(&shared),
            "salt": h(&salt), "info_ascii": "tomi/v1/hkdf/history-transport",
            "transport_key": h(&tk), "nonce": h(&nonce), "aad": h(&aad_t),
            "sealed": h(&m.sealed_key),
        },
        "manifest": {
            "as_of_seq": as_of_seq, "created_at_ms": created_at,
            "signed_bytes": h(&m.signed_bytes()?),
            "signature": h(&m.signature),
            "wire": h(&wire),
            "wire_len": wire.len(),
        },
        "index": index_text,
        "index_sha256": sha(&index),
        "parts": part_values,
        "expected_entries": entries.iter().map(history_entry_value).collect::<Vec<_>>(),
        "expected_summary": {"items": summary.items, "skipped_unreadable": summary.skipped_unreadable, "files_unavailable": summary.files_unavailable},
        "transferred_files": file_values,
        "payloads": payload_values,
        "failures": {
            "manifest": manifest_cases,
            "part": part_cases,
            "index": index_cases,
        },
    }))
}

// ---------------------------------------------------------------- pin (item state)

struct PinInputs<'a> {
    a: &'a Dev,
    b: &'a Dev,
    c: &'a Dev,
    d: &'a Dev,
    k1: &'a SpaceKey,
    k2: &'a SpaceKey,
    rotation_wire: Vec<u8>,
    history_manifest: Vec<u8>,
    id_text: &'a str,
}

fn pin_state_value(s: &PinState) -> Value {
    json!({"pinned": s.pinned, "at_ms": s.at_ms})
}

fn pin_vectors(x: PinInputs<'_>) -> R<Value> {
    let PinInputs {
        a,
        b,
        c,
        d,
        k1,
        k2,
        rotation_wire,
        history_manifest,
        id_text,
    } = x;
    let info = b"tomi/v1/hkdf/item-state";
    let mut key_values = Vec::new();
    for k in [k1, k2] {
        let okm = kat::item_state_key(k)?;
        check(
            kat::hkdf_sha256(&[], &k.to_bytes(), info, 32)? == okm,
            "item state hkdf",
        )?;
        key_values.push(json!({
            "key_epoch": k.epoch(), "space_key": h(&k.to_bytes()), "salt": "",
            "info_ascii": "tomi/v1/hkdf/item-state", "info": h(info), "okm": h(&okm),
        }));
    }

    // --- signed statements
    let at_pin = T0 as u64 + 5_400_000;
    let at_unpin = T0 as u64 + 9_000_000;
    let s_pin = b.keys.sign_pin(SPACE_ID, id_text, at_pin, true)?;
    let s_unpin = a.keys.sign_pin(SPACE_ID, id_text, at_unpin, false)?;
    check(PIN_STATEMENT_LEN == 153, "pin statement length")?;
    let stmt_value = |name: &str, signer: &str, s: &PinStatement| -> R<Value> {
        let wire = s.to_bytes()?;
        check(wire.len() == PIN_STATEMENT_LEN, "pin wire length")?;
        check(PinStatement::from_bytes(&wire)? == *s, "pin roundtrip")?;
        Ok(json!({
            "name": name, "signer": signer, "space_id": s.space_id, "item_id": s.item_id,
            "at_ms": s.at_ms, "pinned": s.pinned,
            "signed_bytes": h(&s.signed_bytes()?), "signature": h(&s.signature),
            "wire": h(&wire), "wire_len": wire.len(),
        }))
    };
    let statements = vec![
        stmt_value("pin_by_b", "B", &s_pin)?,
        stmt_value("unpin_by_a", "A", &s_unpin)?,
    ];

    // --- encrypted envelopes
    let eid1 = "e0000000-0000-4000-8000-000000000001";
    let eid2 = "e0000000-0000-4000-8000-000000000002";
    // (name, statement name, statement, space key, event id, nonce)
    type EnvSpec<'s> = (
        &'s str,
        &'s str,
        &'s PinStatement,
        &'s SpaceKey,
        &'s str,
        Vec<u8>,
    );
    let env_specs: [EnvSpec<'_>; 2] = [
        (
            "pin_by_b_epoch1",
            "pin_by_b",
            &s_pin,
            k1,
            eid1,
            seq(0x30, 24),
        ),
        (
            "unpin_by_a_epoch2",
            "unpin_by_a",
            &s_unpin,
            k2,
            eid2,
            seq(0x48, 24),
        ),
    ];
    let mut envelopes = Vec::new();
    let mut env_bytes = Vec::new();
    for (name, stmt_name, s, k, eid, nonce) in &env_specs {
        let inner = s.to_bytes()?;
        let padded = kat::pad_payload(&inner);
        let aad = kat::aad_item_state(1, k.epoch(), eid)?;
        let key = kat::item_state_key(k)?;
        let ct = kat::xchacha20poly1305_seal(&key, nonce, &aad, &padded)?;
        let env = kat::seal_item_state(&inner, eid, k, nonce)?;
        let mut manual = Vec::new();
        manual.extend_from_slice(&FORMAT_MAX.to_be_bytes());
        manual.extend_from_slice(&k.epoch().to_be_bytes());
        manual.extend_from_slice(uuid::Uuid::parse_str(eid)?.as_bytes());
        manual.extend_from_slice(nonce);
        manual.extend_from_slice(&ct);
        check(manual == env, "item state layout")?;
        check(
            env.len() == ITEM_STATE_ENVELOPE_LEN,
            "item state length 320",
        )?;
        check(aad.len() == 47, "aad state length")?;
        let opened = tomi_core::open_item_state(&env, eid, k)?;
        check(
            opened.state == ItemStateKind::Pin((*s).clone()),
            "item state opens",
        )?;
        envelopes.push(json!({
            "name": name, "statement": stmt_name, "format": 1, "key_epoch": k.epoch(),
            "space_key": h(&k.to_bytes()), "event_id": eid, "nonce": h(nonce),
            "item_state_key": h(&key), "aad": h(&aad), "padded": h(&padded),
            "ciphertext": h(&ct), "envelope": h(&env), "envelope_len": env.len(),
        }));
        env_bytes.push(env);
    }

    // --- convergence (last-writer-wins on (at_ms, pinned))
    let p = |pinned: bool, at_ms: u64| PinState { pinned, at_ms };
    let conv_specs = [
        (
            "later_unpin_wins",
            "Pinned at 100, unpinned at 200: unpinned.",
            vec![p(true, 100), p(false, 200)],
            p(false, 200),
        ),
        (
            "order_independent",
            "Same events received in reverse order: same result.",
            vec![p(false, 200), p(true, 100)],
            p(false, 200),
        ),
        (
            "tie_pinned_wins",
            "Same timestamp: pinned wins (keeping is the safest).",
            vec![p(false, 300), p(true, 300)],
            p(true, 300),
        ),
        (
            "tie_pinned_wins_reversed",
            "Same timestamp, reverse order.",
            vec![p(true, 300), p(false, 300)],
            p(true, 300),
        ),
        (
            "replayed_old_event_ignored",
            "The relay replays an old event: no effect.",
            vec![p(true, 100), p(false, 200), p(true, 100)],
            p(false, 200),
        ),
    ];
    let mut convergence = Vec::new();
    for (name, desc, events, expected) in &conv_specs {
        let mut book = PinBook::new();
        for e in events {
            book.merge(id_text, *e)?;
        }
        check(book.state(id_text) == Some(*expected), name)?;
        convergence.push(json!({
            "name": name, "description": desc,
            "events": events.iter().map(pin_state_value).collect::<Vec<_>>(),
            "expected": pin_state_value(expected),
        }));
    }
    let next_specs = [
        (None, 1_000u64, 1_000u64),
        (Some(p(true, 5_000)), 1_000, 5_001),
        (Some(p(false, 500)), 1_000, 1_000),
    ];
    let mut next_at = Vec::new();
    for (cur, now, expected) in &next_specs {
        check(PinState::next_at_ms(*cur, *now)? == *expected, "next_at")?;
        next_at.push(json!({
            "current": cur.as_ref().map(pin_state_value), "now_ms": now, "expected_at_ms": expected,
        }));
    }

    // --- epoch order rule (same as items)
    let rotation_seq: u64 = 1_793_757_600_000;
    let mut ring = SpaceKeyRing::new(k1.clone());
    let pending = ring.open_received_state(&env_bytes[1], eid2, rotation_seq + 5);
    check(
        pending == ReceivedItemState::Unreadable(UnreadableReason::KeyPending),
        "key pending",
    )?;
    ring.add_rotation_key(k2.clone(), rotation_seq, T0 as u64 + 7_300_000)?;
    let epoch_cases = vec![
        json!({"name": "epoch1_before_rotation", "envelope_of": "pin_by_b_epoch1", "seq": rotation_seq - 1, "expected": "opened"}),
        json!({"name": "epoch1_after_rotation", "envelope_of": "pin_by_b_epoch1", "seq": rotation_seq + 1, "expected": "suspect_epoch"}),
        json!({"name": "epoch2_after_rotation", "envelope_of": "unpin_by_a_epoch2", "seq": rotation_seq + 2, "expected": "opened"}),
    ];
    for case in &epoch_cases {
        let (env, eid) = if case["envelope_of"] == "pin_by_b_epoch1" {
            (&env_bytes[0], eid1)
        } else {
            (&env_bytes[1], eid2)
        };
        let got = match ring.open_received_state(env, eid, case["seq"].as_u64().ok_or("seq")?) {
            ReceivedItemState::Opened(_) => "opened",
            ReceivedItemState::Unreadable(r) => r.code(),
        };
        check(
            Some(got) == case["expected"].as_str(),
            "epoch rule for item states",
        )?;
    }

    // --- history index with pins (manifest of history-transfer.json)
    let m = HistoryTransfer::from_bytes(&history_manifest)?;
    let header = HistoryHeader::for_transfer(&m)?;
    let mk_item = |id: &str, src: &Dev, secret: bool, title: &str, plain: &str| tomi_core::Item {
        id: id.into(),
        source_device: src.keys.device_id(),
        created_at_ms: T0,
        expires_at_ms: None,
        read_policy: tomi_core::ReadPolicy::UntilExpiry,
        secret,
        title: Some(title.into()),
        text: Some(tomi_core::ItemText {
            plain: plain.into(),
            html: None,
            markdown: None,
            source_format: tomi_core::SourceFormat::Plain,
        }),
        url: None,
        attachments: vec![],
        raw_payload: None,
    };
    let hist_items = [
        (
            mk_item(
                "8a8b8c8d-8e8f-4091-8293-949596979899",
                a,
                false,
                "Ticket de caisse",
                "Garantie 2 ans",
            ),
            Some(p(true, at_pin)),
        ),
        (
            mk_item(
                "5c5d5e5f-6061-4263-8465-666768696a6b",
                c,
                true,
                "Code Wi-Fi maison",
                "correct horse battery staple",
            ),
            Some(p(false, at_unpin)),
        ),
        (
            mk_item(
                "9a9b9c9d-9e9f-40a1-82a3-a4a5a6a7a8a9",
                a,
                false,
                "Sans épingle",
                "jamais épinglé",
            ),
            None,
        ),
    ];
    let mut w = HistoryIndexWriter::new(&header)?;
    let mut index = w.header_line()?;
    for (k, (item, pin)) in hist_items.iter().enumerate() {
        index.extend(w.item_line(&HistoryItem {
            item: item.clone(),
            origin_seq: 1_793_750_400_200 + k as u64,
            received_at_ms: T0 + 1_000,
            read: true,
            kept: false,
            files: vec![],
            removed_attachments: vec![],
            pin: *pin,
            archive: None,
        })?);
    }
    index.extend(w.end_line(0)?);
    let mut reader = HistoryIndexReader::new(&m)?;
    let entries = reader.feed(&index)?;
    reader.finish()?;
    let mut expected_pins = Vec::new();
    for ((item, pin), e) in hist_items.iter().zip(&entries) {
        let HistoryEntry::Item(hi) = e else {
            return Err("item entry expected".into());
        };
        check(hi.pin == *pin && hi.item.id == item.id, "history pin")?;
        expected_pins.push(json!({"item_id": item.id, "pin": pin.as_ref().map(pin_state_value)}));
    }

    // --- failures
    let env1 = &env_bytes[0];
    let eid9 = "e0000000-0000-4000-8000-000000000009";
    let mut flip = env1.clone();
    let last = flip.len() - 1;
    flip[last] ^= 0x01;
    let mut rewritten_id = env1.clone();
    rewritten_id[8..24].copy_from_slice(uuid::Uuid::parse_str(eid9)?.as_bytes());
    let mut rewritten_epoch = env_bytes[1].clone();
    rewritten_epoch[4..8].copy_from_slice(&1u32.to_be_bytes());
    let mut format2 = env1.clone();
    format2[0..4].copy_from_slice(&2u32.to_be_bytes());
    let truncated = env1[..env1.len() - 1].to_vec();
    let pin_wire = s_pin.to_bytes()?;
    let short_inner =
        kat::seal_item_state(&pin_wire[..PIN_STATEMENT_LEN - 1], eid1, k1, &seq(0x30, 24))?;
    let mut future_inner = b"tomi/v1/sig/future\0".to_vec();
    future_inner.extend(seq(0x01, 40));
    let unknown_kind = kat::seal_item_state(&future_inner, eid1, k1, &seq(0x30, 24))?;
    let env_case = |name: &str,
                    desc: &str,
                    env: &[u8],
                    announced: &str,
                    epoch: u32,
                    expected: &str| {
        json!({"name": name, "description": desc, "envelope": h(env), "announced_event_id": announced,
               "open_with_key_epoch": epoch, "expected_error": expected})
    };
    let envelope_failures = vec![
        env_case(
            "ciphertext_bit_flip",
            "Last byte (tag) modified.",
            &flip,
            eid1,
            1,
            "decryption_failed",
        ),
        env_case(
            "announced_event_id_differs",
            "The relay lists the event under a different event_id.",
            env1,
            eid9,
            1,
            "event_id_mismatch",
        ),
        env_case(
            "header_event_id_rewritten",
            "Header event_id rewritten (and announced): the AAD no longer matches.",
            &rewritten_id,
            eid9,
            1,
            "decryption_failed",
        ),
        env_case(
            "header_key_epoch_rewritten",
            "Epoch 2 rewritten to 1 and opened with key 1.",
            &rewritten_epoch,
            eid2,
            1,
            "decryption_failed",
        ),
        env_case(
            "unknown_format",
            "format = 2: keep raw and retry after an update.",
            &format2,
            eid1,
            1,
            "unsupported_format",
        ),
        env_case(
            "truncated",
            "One byte fewer.",
            &truncated,
            eid1,
            1,
            "malformed_envelope",
        ),
        env_case(
            "inner_pin_wrong_length",
            "Pin statement truncated by one byte, correctly encrypted.",
            &short_inner,
            eid1,
            1,
            "malformed_statement",
        ),
    ];
    for case in &envelope_failures {
        let env = hex::decode(case["envelope"].as_str().ok_or("env")?)?;
        let k = if case["open_with_key_epoch"] == 1 {
            k1
        } else {
            k2
        };
        let got =
            tomi_core::open_item_state(&env, case["announced_event_id"].as_str().ok_or("id")?, k);
        check(
            got.err().map(|e| e.code()) == case["expected_error"].as_str(),
            case["name"].as_str().ok_or("name")?,
        )?;
    }
    let o = tomi_core::open_item_state(&unknown_kind, eid1, k1)?;
    check(o.state == ItemStateKind::Unknown, "unknown kind ignored")?;

    let mut flipped_state = pin_wire.clone();
    flipped_state[56] = 0x00;
    let mut bad_state = pin_wire.clone();
    bad_state[56] = 0x02;
    // at_ms = 2^53 (first value above PIN_AT_MS_MAX), validly signed by B: the public
    // API refuses to sign it, so the TBS is built and signed by hand.
    let mut too_late = pin_wire[..PIN_STATEMENT_LEN - 64].to_vec();
    too_late[48..56].copy_from_slice(&(1u64 << 53).to_be_bytes());
    let too_late_sig = kat::ed25519_sign(&b.ed_seed, &too_late)?;
    kat::ed25519_verify(&b.public().ed25519, &too_late, &too_late_sig)?;
    too_late.extend_from_slice(&too_late_sig);
    let from_d = d
        .keys
        .sign_pin(SPACE_ID, id_text, at_pin, true)?
        .to_bytes()?;
    let from_c = c
        .keys
        .sign_pin(SPACE_ID, id_text, at_pin, true)?
        .to_bytes()?;
    let other_space = b
        .keys
        .sign_pin(
            "6f2a1d3b-8c4e-4f90-8b72-1d3e5f7a9b21",
            id_text,
            at_pin,
            true,
        )?
        .to_bytes()?;
    let setup = |rot: bool| {
        let mut v = json!({"self": "B", "key_epoch": 1, "members": ["A", "B", "C"]});
        if rot {
            v["apply_rotation"] = json!("rotation.json");
        }
        v
    };
    let stmt_case = |name: &str, desc: &str, wire: &[u8], rot: bool, expected: &str| json!({"name": name, "description": desc, "wire": h(wire), "trust_setup": setup(rot), "expected_error": expected});
    let statement_failures = vec![
        stmt_case(
            "state_flipped",
            "State byte (offset 56) changed from 01 to 00 after signing.",
            &flipped_state,
            false,
            "invalid_signature",
        ),
        stmt_case(
            "unknown_state_byte",
            "State byte 02.",
            &bad_state,
            false,
            "malformed_statement",
        ),
        stmt_case(
            "at_ms_above_2_53_minus_1",
            "at_ms = 2^53 = 9007199254740992 (offset 48), valid signature by B: bound at_ms <= 2^53 - 1.",
            &too_late,
            false,
            "malformed_statement",
        ),
        stmt_case(
            "untrusted_signer",
            "Valid pin signed by D, which is not a member.",
            &from_d,
            false,
            "untrusted_signer",
        ),
        stmt_case(
            "revoked_signer",
            "Pin signed by C, presented to B after rotation.json (C revoked).",
            &from_c,
            true,
            "revoked_device",
        ),
        stmt_case(
            "other_space",
            "Pin signed by B for another space.",
            &other_space,
            false,
            "space_mismatch",
        ),
    ];
    let store = |me: &Dev, rot: bool| -> R<TrustStore> {
        let mut s = TrustStore::new(SPACE_ID, &me.public(), 1)?;
        for o in [a, b, c] {
            s.add_verified_peer(&o.public())?;
        }
        if rot {
            s.apply_rotation(
                &tomi_core::KeyRotation::from_bytes(&rotation_wire)?,
                &me.keys,
            )?;
        }
        Ok(s)
    };
    for case in &statement_failures {
        let st = store(b, case["trust_setup"].get("apply_rotation").is_some())?;
        let w = hex::decode(case["wire"].as_str().ok_or("wire")?)?;
        let got = PinStatement::from_bytes(&w).and_then(|s| st.verify_pin(&s));
        check(
            got.err().map(|e| e.code()) == case["expected_error"].as_str(),
            case["name"].as_str().ok_or("name")?,
        )?;
    }
    store(b, false)?.verify_pin(&s_pin)?;
    store(b, false)?.verify_pin(&s_unpin)?;

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Shared, encrypted pin (§8.8): signed pin/unpin statement (153 bytes), item state envelope encrypted under K_state (320 bytes; the relay sees neither the item_id nor the state), last-writer-wins convergence on (at_ms, pinned), epoch ordering rule, pin field of the history transfer index (manifest of history-transfer.json), and failure cases. Devices in device.json, rotation in rotation.json.",
        "space_id": SPACE_ID,
        "item_state_keys": key_values,
        "statements": statements,
        "envelopes": envelopes,
        "convergence": convergence,
        "next_at": next_at,
        "epoch_rule": {"rotation_seq": rotation_seq, "rotation": "rotation.json (epoch 1 -> 2)", "cases": epoch_cases,
                        "key_pending": {"envelope_of": "unpin_by_a_epoch2", "ring_epochs": [1], "expected": "key_pending"}},
        "history_index": {
            "manifest_from": "history-transfer.json",
            "index": String::from_utf8(index.clone())?,
            "expected_pins": expected_pins,
        },
        "unknown_kind": {"description": "State content of an unknown type (unknown inner label): ignored, without error.",
                         "envelope": h(&unknown_kind), "event_id": eid1, "key_epoch": 1, "inner": h(&future_inner), "expected": "unknown"},
        "failures": {
            "envelope": envelope_failures,
            "statement": statement_failures,
        },
    }))
}

// ---------------------------------------------------------------- attachment tombstone

const BLOB_ID_1: &str = "7c1d9e2a-4b3f-4a5c-8d6e-9f0a1b2c3d4e";
const BLOB_ID_2: &str = "8d2eaf3b-5c4a-4b6d-9e7f-a01b2c3d4e5f";

/// `attachment-tombstone.json` (§8.10): the removal of one attachment, signed under its own
/// label. Failure cases live in the same file (`failures.json` is frozen).
fn attachment_tombstone_vectors(
    a: &Dev,
    b: &Dev,
    c: &Dev,
    d: &Dev,
    id_text: &str,
    id_secret: &str,
    issued: u64,
) -> R<Value> {
    let trust = json!({"self": "A", "key_epoch": 1, "members": ["A", "B", "C"]});
    let at = issued + 3_600_000;
    let t_b = b
        .keys
        .sign_attachment_tombstone(SPACE_ID, id_text, BLOB_ID_1, 1, at)?;
    // Edges: the largest slot and the largest time.
    let t_a = a.keys.sign_attachment_tombstone(
        SPACE_ID,
        id_secret,
        BLOB_ID_2,
        u32::MAX,
        ATTACHMENT_TOMBSTONE_AT_MS_MAX,
    )?;
    check(
        ATTACHMENT_TOMBSTONE_LEN == 189,
        "attachment tombstone length",
    )?;
    let vec_of = |t: &tomi_core::AttachmentTombstone, signer: &str| -> R<Value> {
        let wire = t.to_bytes()?;
        check(
            wire.len() == ATTACHMENT_TOMBSTONE_LEN,
            "attachment tombstone wire",
        )?;
        check(
            &tomi_core::AttachmentTombstone::from_bytes(&wire)? == t,
            "attachment tombstone roundtrip",
        )?;
        Ok(json!({
            "signer": signer, "space_id": t.space_id, "item_id": t.item_id,
            "blob_id": t.blob_id, "slot": t.slot, "deleted_at_ms": t.deleted_at_ms,
            "signed_bytes": h(&t.signed_bytes()?),
            "signature": h(&t.signature),
            "wire": h(&wire),
        }))
    };

    // --- failures
    let good = t_b.to_bytes()?;
    // Offsets: label (32) + 0x00, then space, item, blob (16 each), slot (4), time (8).
    let off_item = 33 + 16;
    let off_blob = off_item + 16;
    let off_slot = off_blob + 16;
    let off_time = off_slot + 4;
    let mut slot_x = good.clone();
    slot_x[off_slot + 3] ^= 0x01; // slot 1 -> 0
    let mut blob_x = good.clone();
    blob_x[off_blob + 15] ^= 0x01;
    let mut item_x = good.clone();
    item_x[off_item + 15] ^= 0x01;
    let mut time_x = good.clone();
    time_x[off_time + 7] ^= 0x01;
    let mut flip = good.clone();
    let last = flip.len() - 1;
    flip[last] ^= 0x01;
    let mut extra = good.clone();
    extra.push(0);
    let short = good[..good.len() - 1].to_vec();
    // 2^53, validly signed: the parser must refuse it before any signature check.
    let mut tbs_big = good[..good.len() - 64].to_vec();
    tbs_big[off_time..off_time + 8].copy_from_slice(&(1u64 << 53).to_be_bytes());
    let mut wire_big = tbs_big.clone();
    wire_big.extend(kat::ed25519_sign(&b.ed_seed, &tbs_big)?);
    let item_tomb = b
        .keys
        .sign_tombstone(SPACE_ID, id_text, at, DeletionScope::Everywhere)?;
    let by_d = d
        .keys
        .sign_attachment_tombstone(SPACE_ID, id_text, BLOB_ID_1, 1, at)?;
    let by_c = c
        .keys
        .sign_attachment_tombstone(SPACE_ID, id_text, BLOB_ID_1, 1, at)?;
    let other_space = b.keys.sign_attachment_tombstone(
        "6f2a1d3b-8c4e-4f90-a172-1d3e5f708192",
        id_text,
        BLOB_ID_1,
        1,
        at,
    )?;
    let case = |name: &str, description: &str, kind: &str, wire: &[u8], err: &str| -> Value {
        json!({
            "name": name, "description": description, "kind": kind, "wire": h(wire),
            "trust_setup": trust, "expected_error": err,
        })
    };
    let failures = vec![
        case(
            "item_tombstone_is_not_an_attachment_removal",
            "An item tombstone (different label and length) presented as an attachment removal.",
            "attachment_tombstone",
            &item_tomb.to_bytes()?,
            "malformed_statement",
        ),
        case(
            "attachment_removal_is_not_an_item_tombstone",
            "An attachment removal presented as an item tombstone.",
            "tombstone",
            &good,
            "malformed_statement",
        ),
        case(
            "slot_altered",
            "Slot rewritten (1 -> 0) after signing.",
            "attachment_tombstone",
            &slot_x,
            "invalid_signature",
        ),
        case(
            "blob_id_altered",
            "blob_id rewritten after signing.",
            "attachment_tombstone",
            &blob_x,
            "invalid_signature",
        ),
        case(
            "item_id_altered",
            "item_id rewritten after signing.",
            "attachment_tombstone",
            &item_x,
            "invalid_signature",
        ),
        case(
            "deleted_at_altered",
            "Date rewritten after signing.",
            "attachment_tombstone",
            &time_x,
            "invalid_signature",
        ),
        case(
            "deleted_at_above_2_53_minus_1",
            "deleted_at_ms = 2^53, valid signature: refused at parsing (malformed_statement).",
            "attachment_tombstone",
            &wire_big,
            "malformed_statement",
        ),
        case(
            "signature_bit_flip",
            "One bit of the signature flipped.",
            "attachment_tombstone",
            &flip,
            "invalid_signature",
        ),
        case(
            "one_byte_too_many",
            "Exact length required: one byte too many.",
            "attachment_tombstone",
            &extra,
            "malformed_statement",
        ),
        case(
            "one_byte_too_few",
            "Exact length required: one byte fewer.",
            "attachment_tombstone",
            &short,
            "malformed_statement",
        ),
        case(
            "untrusted_signer",
            "Valid signature by D, which is not a member.",
            "attachment_tombstone",
            &by_d.to_bytes()?,
            "untrusted_signer",
        ),
        json!({
            "name": "revoked_signer",
            "description": "Valid signature by C, presented to B after rotation.json (C revoked).",
            "kind": "attachment_tombstone", "wire": h(&by_c.to_bytes()?),
            "trust_setup": {
                "self": "B", "key_epoch": 1, "members": ["A", "B", "C"],
                "apply_rotation": "rotation.json",
            },
            "expected_error": "revoked_device",
        }),
        case(
            "other_space",
            "Valid signature, but for another space.",
            "attachment_tombstone",
            &other_space.to_bytes()?,
            "space_mismatch",
        ),
    ];
    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Removal of ONE attachment (§8.10): TBS = label tomi/v1/sig/attachment-tombstone || 0x00 || space_id(16) || item_id(16) || blob_id(16) || u32be(slot) || u64be(deleted_at_ms) || signer_ed_pk(32), wire = TBS || signature(64) = 189 bytes. deleted_at_ms <= 2^53 - 1. Devices in device.json. Only one scope circulates (everywhere): no scope byte. Failure cases: kind = attachment_tombstone or tombstone (parsed with that type), then verification against trust_setup.",
        "vectors": [vec_of(&t_b, "B")?, vec_of(&t_a, "A")?],
        "failures": failures,
    }))
}

// ---------------------------------------------------------------- archive (item state)

fn archive_state_value(s: &ArchiveState) -> Value {
    json!({"archived": s.archived, "at_ms": s.at_ms})
}

/// `archive.json` (§8.9): the twin of `pin.json`, same devices, same keys, same item.
fn archive_vectors(x: PinInputs<'_>) -> R<Value> {
    let PinInputs {
        a,
        b,
        c,
        d,
        k1,
        k2,
        rotation_wire,
        history_manifest,
        id_text,
    } = x;
    let info = b"tomi/v1/hkdf/item-state";
    let mut key_values = Vec::new();
    for k in [k1, k2] {
        let okm = kat::item_state_key(k)?;
        check(
            kat::hkdf_sha256(&[], &k.to_bytes(), info, 32)? == okm,
            "item state hkdf",
        )?;
        key_values.push(json!({
            "key_epoch": k.epoch(), "space_key": h(&k.to_bytes()), "salt": "",
            "info_ascii": "tomi/v1/hkdf/item-state", "info": h(info), "okm": h(&okm),
        }));
    }

    // --- signed statements
    let at_archive = T0 as u64 + 6_000_000;
    let at_unarchive = T0 as u64 + 9_600_000;
    let s_arc = b.keys.sign_archive(SPACE_ID, id_text, at_archive, true)?;
    let s_unarc = a
        .keys
        .sign_archive(SPACE_ID, id_text, at_unarchive, false)?;
    check(ARCHIVE_STATEMENT_LEN == 157, "archive statement length")?;
    let stmt_value = |name: &str, signer: &str, s: &ArchiveStatement| -> R<Value> {
        let wire = s.to_bytes()?;
        check(wire.len() == ARCHIVE_STATEMENT_LEN, "archive wire length")?;
        check(
            ArchiveStatement::from_bytes(&wire)? == *s,
            "archive roundtrip",
        )?;
        Ok(json!({
            "name": name, "signer": signer, "space_id": s.space_id, "item_id": s.item_id,
            "at_ms": s.at_ms, "archived": s.archived,
            "signed_bytes": h(&s.signed_bytes()?), "signature": h(&s.signature),
            "wire": h(&wire), "wire_len": wire.len(),
        }))
    };
    let statements = vec![
        stmt_value("archive_by_b", "B", &s_arc)?,
        stmt_value("unarchive_by_a", "A", &s_unarc)?,
    ];

    // --- encrypted envelopes (same 320-byte shape as a pin)
    let eid1 = "e0000000-0000-4000-8000-0000000000a1";
    let eid2 = "e0000000-0000-4000-8000-0000000000a2";
    type EnvSpec<'s> = (
        &'s str,
        &'s str,
        &'s ArchiveStatement,
        &'s SpaceKey,
        &'s str,
        Vec<u8>,
    );
    let env_specs: [EnvSpec<'_>; 2] = [
        (
            "archive_by_b_epoch1",
            "archive_by_b",
            &s_arc,
            k1,
            eid1,
            seq(0x60, 24),
        ),
        (
            "unarchive_by_a_epoch2",
            "unarchive_by_a",
            &s_unarc,
            k2,
            eid2,
            seq(0x78, 24),
        ),
    ];
    let mut envelopes = Vec::new();
    let mut env_bytes = Vec::new();
    for (name, stmt_name, s, k, eid, nonce) in &env_specs {
        let inner = s.to_bytes()?;
        let padded = kat::pad_payload(&inner);
        let aad = kat::aad_item_state(1, k.epoch(), eid)?;
        let key = kat::item_state_key(k)?;
        let ct = kat::xchacha20poly1305_seal(&key, nonce, &aad, &padded)?;
        let env = kat::seal_item_state(&inner, eid, k, nonce)?;
        let mut manual = Vec::new();
        manual.extend_from_slice(&FORMAT_MAX.to_be_bytes());
        manual.extend_from_slice(&k.epoch().to_be_bytes());
        manual.extend_from_slice(uuid::Uuid::parse_str(eid)?.as_bytes());
        manual.extend_from_slice(nonce);
        manual.extend_from_slice(&ct);
        check(manual == env, "archive item state layout")?;
        check(
            env.len() == ITEM_STATE_ENVELOPE_LEN,
            "archive item state length 320",
        )?;
        let opened = tomi_core::open_item_state(&env, eid, k)?;
        check(
            opened.state == ItemStateKind::Archive((*s).clone()),
            "archive item state opens",
        )?;
        envelopes.push(json!({
            "name": name, "statement": stmt_name, "format": 1, "key_epoch": k.epoch(),
            "space_key": h(&k.to_bytes()), "event_id": eid, "nonce": h(nonce),
            "item_state_key": h(&key), "aad": h(&aad), "padded": h(&padded),
            "ciphertext": h(&ct), "envelope": h(&env), "envelope_len": env.len(),
        }));
        env_bytes.push(env);
    }

    // --- convergence (last-writer-wins on (at_ms, archived))
    let p = |archived: bool, at_ms: u64| ArchiveState { archived, at_ms };
    let conv_specs = [
        (
            "later_unarchive_wins",
            "Archived at 100, unarchived at 200: unarchived.",
            vec![p(true, 100), p(false, 200)],
            p(false, 200),
        ),
        (
            "order_independent",
            "Same events received in reverse order: same result.",
            vec![p(false, 200), p(true, 100)],
            p(false, 200),
        ),
        (
            "tie_archived_wins",
            "Same timestamp: archived wins.",
            vec![p(false, 300), p(true, 300)],
            p(true, 300),
        ),
        (
            "tie_archived_wins_reversed",
            "Same timestamp, reverse order.",
            vec![p(true, 300), p(false, 300)],
            p(true, 300),
        ),
        (
            "replayed_old_event_ignored",
            "The relay replays an old event: no effect.",
            vec![p(true, 100), p(false, 200), p(true, 100)],
            p(false, 200),
        ),
    ];
    let mut convergence = Vec::new();
    for (name, desc, events, expected) in &conv_specs {
        let mut book = ArchiveBook::new();
        for e in events {
            book.merge(id_text, *e)?;
        }
        check(book.state(id_text) == Some(*expected), name)?;
        convergence.push(json!({
            "name": name, "description": desc,
            "events": events.iter().map(archive_state_value).collect::<Vec<_>>(),
            "expected": archive_state_value(expected),
        }));
    }
    let next_specs = [
        (None, 1_000u64, 1_000u64),
        (Some(p(true, 5_000)), 1_000, 5_001),
        (Some(p(false, 500)), 1_000, 1_000),
    ];
    let mut next_at = Vec::new();
    for (cur, now, expected) in &next_specs {
        check(
            ArchiveState::next_at_ms(*cur, *now)? == *expected,
            "archive next_at",
        )?;
        next_at.push(json!({
            "current": cur.as_ref().map(archive_state_value), "now_ms": now, "expected_at_ms": expected,
        }));
    }

    // --- epoch order rule (same as items and pins)
    let rotation_seq: u64 = 1_793_757_600_000;
    let mut ring = SpaceKeyRing::new(k1.clone());
    let pending = ring.open_received_state(&env_bytes[1], eid2, rotation_seq + 5);
    check(
        pending == ReceivedItemState::Unreadable(UnreadableReason::KeyPending),
        "archive key pending",
    )?;
    ring.add_rotation_key(k2.clone(), rotation_seq, T0 as u64 + 7_300_000)?;
    let epoch_cases = vec![
        json!({"name": "epoch1_before_rotation", "envelope_of": "archive_by_b_epoch1", "seq": rotation_seq - 1, "expected": "opened"}),
        json!({"name": "epoch1_after_rotation", "envelope_of": "archive_by_b_epoch1", "seq": rotation_seq + 1, "expected": "suspect_epoch"}),
        json!({"name": "epoch2_after_rotation", "envelope_of": "unarchive_by_a_epoch2", "seq": rotation_seq + 2, "expected": "opened"}),
    ];
    for case in &epoch_cases {
        let (env, eid) = if case["envelope_of"] == "archive_by_b_epoch1" {
            (&env_bytes[0], eid1)
        } else {
            (&env_bytes[1], eid2)
        };
        let got = match ring.open_received_state(env, eid, case["seq"].as_u64().ok_or("seq")?) {
            ReceivedItemState::Opened(_) => "opened",
            ReceivedItemState::Unreadable(r) => r.code(),
        };
        check(
            Some(got) == case["expected"].as_str(),
            "epoch rule for archive states",
        )?;
    }

    // --- history index with the `archive` field (manifest of history-transfer.json)
    let m = HistoryTransfer::from_bytes(&history_manifest)?;
    let header = HistoryHeader::for_transfer(&m)?;
    let mk_item = |id: &str, src: &Dev, secret: bool, title: &str, plain: &str| tomi_core::Item {
        id: id.into(),
        source_device: src.keys.device_id(),
        created_at_ms: T0,
        expires_at_ms: None,
        read_policy: tomi_core::ReadPolicy::UntilExpiry,
        secret,
        title: Some(title.into()),
        text: Some(tomi_core::ItemText {
            plain: plain.into(),
            html: None,
            markdown: None,
            source_format: tomi_core::SourceFormat::Plain,
        }),
        url: None,
        attachments: vec![],
        raw_payload: None,
    };
    // (item, pin, archive): a secret is transferred and archived like any item; the last item
    // carries both states (crossing decisions: the pin wins at display, §8.9.3).
    let hist_items = [
        (
            mk_item(
                "8a8b8c8d-8e8f-4091-8293-949596979899",
                a,
                false,
                "Ticket de caisse",
                "Garantie 2 ans",
            ),
            None,
            Some(p(true, at_archive)),
        ),
        (
            mk_item(
                "5c5d5e5f-6061-4263-8465-666768696a6b",
                c,
                true,
                "Code Wi-Fi maison",
                "correct horse battery staple",
            ),
            None,
            Some(p(false, at_unarchive)),
        ),
        (
            mk_item(
                "9a9b9c9d-9e9f-40a1-82a3-a4a5a6a7a8a9",
                a,
                false,
                "Sans archive",
                "jamais archivé",
            ),
            None,
            None,
        ),
        (
            mk_item(
                "7a7b7c7d-7e7f-4081-8283-848586878889",
                b,
                false,
                "Épinglé et archivé",
                "croisement de décisions",
            ),
            Some(PinState {
                pinned: true,
                at_ms: at_archive,
            }),
            Some(p(true, at_archive + 1)),
        ),
    ];
    let mut w = HistoryIndexWriter::new(&header)?;
    let mut index = w.header_line()?;
    for (k, (item, pin, archive)) in hist_items.iter().enumerate() {
        index.extend(w.item_line(&HistoryItem {
            item: item.clone(),
            origin_seq: 1_793_750_400_300 + k as u64,
            received_at_ms: T0 + 1_000,
            read: true,
            kept: false,
            files: vec![],
            removed_attachments: vec![],
            pin: *pin,
            archive: *archive,
        })?);
    }
    index.extend(w.end_line(0)?);
    let mut reader = HistoryIndexReader::new(&m)?;
    let entries = reader.feed(&index)?;
    reader.finish()?;
    let mut expected_states = Vec::new();
    for ((item, pin, archive), e) in hist_items.iter().zip(&entries) {
        let HistoryEntry::Item(hi) = e else {
            return Err("item entry expected".into());
        };
        check(
            hi.archive == *archive && hi.pin == *pin && hi.item.id == item.id,
            "history archive",
        )?;
        expected_states.push(json!({
            "item_id": item.id,
            "pin": pin.as_ref().map(pin_state_value),
            "archive": archive.as_ref().map(archive_state_value),
        }));
    }

    // --- cross-kind and unknown kind
    let pin_wire = b
        .keys
        .sign_pin(SPACE_ID, id_text, at_archive, true)?
        .to_bytes()?;
    let arc_wire = s_arc.to_bytes()?;
    check(
        ArchiveStatement::from_bytes(&pin_wire).is_err()
            && PinStatement::from_bytes(&arc_wire).is_err(),
        "a pin is not an archive statement",
    )?;
    let pin_in_state = kat::seal_item_state(&pin_wire, eid1, k1, &seq(0x60, 24))?;
    check(
        matches!(
            tomi_core::open_item_state(&pin_in_state, eid1, k1)?.state,
            ItemStateKind::Pin(_)
        ),
        "the inner label selects the kind (pin)",
    )?;
    let mut future_inner = b"tomi/v1/sig/future\0".to_vec();
    future_inner.extend(seq(0x01, 40));
    let unknown_kind = kat::seal_item_state(&future_inner, eid1, k1, &seq(0x60, 24))?;
    let o = tomi_core::open_item_state(&unknown_kind, eid1, k1)?;
    check(o.state == ItemStateKind::Unknown, "unknown kind ignored")?;

    // --- failures
    let env1 = &env_bytes[0];
    let eid9 = "e0000000-0000-4000-8000-000000000009";
    let mut flip = env1.clone();
    let last = flip.len() - 1;
    flip[last] ^= 0x01;
    let mut rewritten_id = env1.clone();
    rewritten_id[8..24].copy_from_slice(uuid::Uuid::parse_str(eid9)?.as_bytes());
    let truncated = env1[..env1.len() - 1].to_vec();
    let short_inner = kat::seal_item_state(
        &arc_wire[..ARCHIVE_STATEMENT_LEN - 1],
        eid1,
        k1,
        &seq(0x60, 24),
    )?;
    let env_case = |name: &str, desc: &str, env: &[u8], announced: &str, expected: &str| {
        json!({"name": name, "description": desc, "envelope": h(env), "announced_event_id": announced,
               "open_with_key_epoch": 1, "expected_error": expected})
    };
    let envelope_failures = vec![
        env_case(
            "ciphertext_bit_flip",
            "Last byte (tag) modified.",
            &flip,
            eid1,
            "decryption_failed",
        ),
        env_case(
            "announced_event_id_differs",
            "The relay lists the event under a different event_id.",
            env1,
            eid9,
            "event_id_mismatch",
        ),
        env_case(
            "header_event_id_rewritten",
            "Header event_id rewritten (and announced): the AAD no longer matches.",
            &rewritten_id,
            eid9,
            "decryption_failed",
        ),
        env_case(
            "truncated",
            "One byte fewer.",
            &truncated,
            eid1,
            "malformed_envelope",
        ),
        env_case(
            "inner_archive_wrong_length",
            "Archive statement truncated by one byte, correctly encrypted.",
            &short_inner,
            eid1,
            "malformed_statement",
        ),
    ];
    for case in &envelope_failures {
        let env = hex::decode(case["envelope"].as_str().ok_or("env")?)?;
        let got =
            tomi_core::open_item_state(&env, case["announced_event_id"].as_str().ok_or("id")?, k1);
        check(
            got.err().map(|e| e.code()) == case["expected_error"].as_str(),
            case["name"].as_str().ok_or("name")?,
        )?;
    }

    // The state byte is at offset 60, at_ms at 52 (TBS = label 19 + 0x00 + 16 + 16 + 8 + 1 + 32).
    let mut flipped_state = arc_wire.clone();
    flipped_state[60] = 0x00;
    let mut bad_state = arc_wire.clone();
    bad_state[60] = 0x02;
    let mut too_late = arc_wire[..ARCHIVE_STATEMENT_LEN - 64].to_vec();
    too_late[52..60].copy_from_slice(&(1u64 << 53).to_be_bytes());
    let too_late_sig = kat::ed25519_sign(&b.ed_seed, &too_late)?;
    kat::ed25519_verify(&b.public().ed25519, &too_late, &too_late_sig)?;
    too_late.extend_from_slice(&too_late_sig);
    let from_d = d
        .keys
        .sign_archive(SPACE_ID, id_text, at_archive, true)?
        .to_bytes()?;
    let from_c = c
        .keys
        .sign_archive(SPACE_ID, id_text, at_archive, true)?
        .to_bytes()?;
    let other_space = b
        .keys
        .sign_archive(
            "6f2a1d3b-8c4e-4f90-8b72-1d3e5f7a9b21",
            id_text,
            at_archive,
            true,
        )?
        .to_bytes()?;
    let setup = |rot: bool| {
        let mut v = json!({"self": "B", "key_epoch": 1, "members": ["A", "B", "C"]});
        if rot {
            v["apply_rotation"] = json!("rotation.json");
        }
        v
    };
    let stmt_case = |name: &str, desc: &str, wire: &[u8], rot: bool, expected: &str| json!({"name": name, "description": desc, "wire": h(wire), "trust_setup": setup(rot), "expected_error": expected});
    let statement_failures = vec![
        stmt_case(
            "state_flipped",
            "State byte (offset 60) changed from 01 to 00 after signing.",
            &flipped_state,
            false,
            "invalid_signature",
        ),
        stmt_case(
            "unknown_state_byte",
            "State byte 02.",
            &bad_state,
            false,
            "malformed_statement",
        ),
        stmt_case(
            "at_ms_above_2_53_minus_1",
            "at_ms = 2^53 = 9007199254740992 (offset 52), valid signature by B: bound at_ms <= 2^53 - 1.",
            &too_late,
            false,
            "malformed_statement",
        ),
        stmt_case(
            "untrusted_signer",
            "Valid archive signed by D, which is not a member.",
            &from_d,
            false,
            "untrusted_signer",
        ),
        stmt_case(
            "revoked_signer",
            "Archive signed by C, presented to B after rotation.json (C revoked).",
            &from_c,
            true,
            "revoked_device",
        ),
        stmt_case(
            "other_space",
            "Archive signed by B for another space.",
            &other_space,
            false,
            "space_mismatch",
        ),
        stmt_case(
            "pin_statement_is_not_an_archive",
            "A pin statement (label tomi/v1/sig/pin) read as an archive statement.",
            &pin_wire,
            false,
            "malformed_statement",
        ),
    ];
    let store = |me: &Dev, rot: bool| -> R<TrustStore> {
        let mut s = TrustStore::new(SPACE_ID, &me.public(), 1)?;
        for o in [a, b, c] {
            s.add_verified_peer(&o.public())?;
        }
        if rot {
            s.apply_rotation(
                &tomi_core::KeyRotation::from_bytes(&rotation_wire)?,
                &me.keys,
            )?;
        }
        Ok(s)
    };
    for case in &statement_failures {
        let st = store(b, case["trust_setup"].get("apply_rotation").is_some())?;
        let w = hex::decode(case["wire"].as_str().ok_or("wire")?)?;
        let got = ArchiveStatement::from_bytes(&w).and_then(|s| st.verify_archive(&s));
        check(
            got.err().map(|e| e.code()) == case["expected_error"].as_str(),
            case["name"].as_str().ok_or("name")?,
        )?;
    }
    store(b, false)?.verify_archive(&s_arc)?;
    store(b, false)?.verify_archive(&s_unarc)?;

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Shared, encrypted archive (§8.9), twin of pin.json: signed archive/unarchive statement (157 bytes, label tomi/v1/sig/archive), item state envelope encrypted under K_state (320 bytes, identical to a pin's for the relay), last-writer-wins convergence on (at_ms, archived), epoch ordering rule, archive field of the history transfer index (manifest of history-transfer.json), distinction of types by the inner label, and failure cases. Devices in device.json, rotation in rotation.json.",
        "space_id": SPACE_ID,
        "item_state_keys": key_values,
        "statements": statements,
        "envelopes": envelopes,
        "convergence": convergence,
        "next_at": next_at,
        "epoch_rule": {"rotation_seq": rotation_seq, "rotation": "rotation.json (epoch 1 -> 2)", "cases": epoch_cases,
                        "key_pending": {"envelope_of": "unarchive_by_a_epoch2", "ring_epochs": [1], "expected": "key_pending"}},
        "history_index": {
            "manifest_from": "history-transfer.json",
            "index": String::from_utf8(index.clone())?,
            "expected_states": expected_states,
        },
        "kinds": {
            "description": "The type of an item state is given by the inner label of the decrypted content. A pin encrypted with the same keys opens as a Pin; a state with an unknown label is ignored without error, as a device that predates archiving does when it meets an archive.",
            "pin_in_state_envelope": h(&pin_in_state), "pin_event_id": eid1, "pin_key_epoch": 1,
            "unknown_kind": {"envelope": h(&unknown_kind), "event_id": eid1, "key_epoch": 1, "inner": h(&future_inner), "expected": "unknown"},
        },
        "failures": {
            "envelope": envelope_failures,
            "statement": statement_failures,
        },
    }))
}

// ---------------------------------------------------------------- payload extensions

/// Duplicate keys at every depth (§5.4) and preservation of unknown fields (§5.4.4).
fn payload_extension_vectors(a: &Dev) -> R<Value> {
    let item_id = "5a5b5c5d-5e5f-4061-8263-646566676869";
    let source = a.keys.device_id();
    let head = format!(r#"{{"id":"{item_id}","source_device":"{source}","created_at":{T0}"#);
    let key_b64 = B64.encode(seq(0x40, 32));
    let prefix_b64 = B64.encode(seq(0x60, 19));
    let attachment = |inner: &str| {
        format!(
            r#","attachments":[{{"blob_id":"6a6b6c6d-6e6f-4071-8273-747576777879","name":"a.txt","mime":"text/plain","size":3,"key":"{key_b64}","nonce_prefix":"{prefix_b64}"{inner}}}]"#
        )
    };

    // -- duplicate keys: every case is `malformed_payload`.
    let dup_cases: Vec<(&str, &str, String)> = vec![
        (
            "reserved_field_twice",
            "The reserved audience field twice (different values): ambiguity between implementations.",
            format!(r#"{head},"audience":{{"to":[]}},"audience":null}}"#),
        ),
        (
            "unknown_field_twice_same_value",
            "An unknown field twice, even with the same value: rejected.",
            format!(r#"{head},"x_future":1,"x_future":1}}"#),
        ),
        (
            "unknown_field_in_known_object",
            "Unknown field duplicated inside the known object text.",
            format!(r#"{head},"text":{{"plain":"x","lang":"fr","lang":"en"}}}}"#),
        ),
        (
            "inside_audience_entry",
            "Duplicate in an audience.to entry, object nested in an array inside an ignored field.",
            format!(
                r#"{head},"audience":{{"to":[{{"type":"device","id":"{source}","id":"{item_id}"}}]}}}}"#
            ),
        ),
        (
            "escaped_spelling_of_same_key",
            "The same key written with an escape sequence (\\u0061 = a): compare the decoded keys.",
            format!(r#"{head},"audience":1,"\u0061udience":2}}"#),
        ),
        (
            "known_field_twice_escaped",
            "Known field secret twice, the second time with an escape (\\u0065 = e).",
            format!(r#"{head},"secret":true,"secr\u0065t":false}}"#),
        ),
        (
            "inside_thumbnail",
            "Duplicate in thumbnail, object nested in attachments[0].",
            format!(
                "{head}{}}}",
                attachment(r#","thumbnail":{"mime":"image/png","data":"AAEC","w":1,"w":2}"#)
            ),
        ),
        (
            "deeply_nested",
            "Duplicate at five levels, followed by a valid field: reading does not stop at the first level.",
            format!(r#"{head},"x":{{"d":[[{{"y":0,"z":0,"y":1}}]]}},"after":1}}"#),
        ),
    ];
    let mut dups = Vec::new();
    for (name, description, json_s) in &dup_cases {
        let got = kat::parse_payload(json_s.as_bytes(), item_id);
        check(
            got.as_ref().err().map(|e| e.code()) == Some("malformed_payload"),
            name,
        )?;
        dups.push(json!({
            "name": name, "description": description,
            "expected_item_id": item_id, "json": json_s, "json_hex": h(json_s.as_bytes()),
            "expected_error": "malformed_payload",
        }));
    }

    // -- the same key in different objects is not a duplicate.
    let ok_cases: Vec<(&str, &str, String)> = vec![
        (
            "same_key_in_sibling_objects",
            "The key x in sibling objects (unknown fields): not a duplicate.",
            format!(r#"{head},"a":{{"x":1}},"b":{{"x":2}},"c":[{{"x":1}},{{"x":2}}]}}"#),
        ),
        (
            "same_key_at_nested_depths",
            "The key a at three depths: not a duplicate.",
            format!(r#"{head},"a":{{"a":{{"a":1}}}}}}"#),
        ),
        (
            "keys_differing_by_case",
            "Audience and audience are two distinct keys (exact comparison).",
            format!(r#"{head},"Audience":1,"audience":2}}"#),
        ),
    ];
    let mut accepted = Vec::new();
    for (name, description, json_s) in &ok_cases {
        let item = kat::parse_payload(json_s.as_bytes(), item_id)?;
        accepted.push(json!({
            "name": name, "description": description,
            "expected_item_id": item_id, "json": json_s, "json_hex": h(json_s.as_bytes()),
            "expected_item": kat::item_to_value(&item),
        }));
    }

    // -- unknown fields must survive local re-sealing and history export (§5.4.4).
    let keep_cases: Vec<(&str, &str, String)> = vec![
        (
            "unknown_fields_at_every_depth",
            "Unknown fields at the root, in text, in attachments[0] and in thumbnail, plus the reserved audience.",
            format!(
                r#"{head},"future_flag":true,"audience":{{"to":[{{"type":"device","id":"{source}","role":"cc"}}],"mode":2}},"text":{{"plain":"x","lang":"fr","spans":[1,{{"k":null}}]}}{},"ext":{{"x":1}}}}"#,
                attachment(
                    r#","duration_ms":1200,"thumbnail":{"mime":"image/png","data":"AAEC","w":16}"#
                )
            ),
        ),
        (
            "secret_with_unknown_fields",
            "Secret with a title: the title and the unknown fields are kept inside the ciphertext, nothing appears in clear.",
            format!(
                r#"{head},"secret":true,"title":"Code Wi-Fi","text":{{"plain":"hunter2"}},"audience":null,"x_other":[]}}"#
            ),
        ),
        (
            "formatting_is_not_normalised",
            "Field order, whitespace, escapes (\\u00e9, \\/) and number spellings (1.0, 1E2, -0) must be preserved as they are.",
            format!(
                r#"{{ "x_num" : [1.0, 1E2, -0, 2.50] , "text" : {{"plain":"caf\u00e9 \/ x"}} , "created_at":{T0},"source_device":"{source}", "id" : "{item_id}" , "x_after":"\u00e9" }}"#
            ),
        ),
    ];
    let local = tomi_core::LocalKey::generate()?;
    let mut keeps = Vec::new();
    for (name, description, json_s) in &keep_cases {
        let item = kat::parse_payload(json_s.as_bytes(), item_id)?;
        check(
            item.raw_payload.as_ref().map(|r| r.as_bytes()) == Some(json_s.as_bytes()),
            name,
        )?;
        let reopened = local.open_item(&local.seal_item(&item)?, item_id)?;
        check(
            reopened.raw_payload.as_ref().map(|r| r.as_bytes()) == Some(json_s.as_bytes()),
            name,
        )?;
        keeps.push(json!({
            "name": name, "description": description,
            "expected_item_id": item_id, "json": json_s, "json_hex": h(json_s.as_bytes()),
            "expected_item": kat::item_to_value(&item),
        }));
    }

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Payload extensibility (§5.4, §5.4.4). duplicate_keys: read json_hex, MUST fail with expected_error (a key repeated in an object, at any depth, known or not, keys compared after decoding the escapes). accepted: read json_hex, MUST yield expected_item. preserved: read json_hex (MUST yield expected_item), then locally re-seal the item (§7.2) and export it into a history transfer index (§8.7.3): the decrypted payload bytes, or the payload value of the item line (compact JSON, no line break), MUST be exactly json_hex. Unknown fields are never lost, and the title and content of a secret stay inside the ciphertext.",
        "duplicate_keys": dups,
        "accepted": accepted,
        "preserved": keeps,
    }))
}

// ---------------------------------------------------------------- reservations

/// First value of the reserved `key_epoch` range used by the vectors (spec §5.8.2).
const RESERVED_KEY_ID: u32 = 0x8000_0001;

/// Item envelope whose header announces a reserved key id. The bytes after the header
/// follow §5 with an arbitrary key: format 1 does not say how such a key encrypts, and a
/// v1 reader never tries to open it.
fn reserved_item_envelope(key: &[u8], item_id: &str, json_s: &str) -> R<(Value, Vec<u8>)> {
    let cek = seq(0x90, 32);
    let wrap_nonce = seq(0xa8, 24);
    let payload_nonce = seq(0xc8, 24);
    let kw = kat::hkdf_sha256(&[], key, b"tomi/v1/hkdf/cek-wrap", 32)?;
    let aad_w = kat::aad_cek_wrap(FORMAT_MAX, RESERVED_KEY_ID, item_id)?;
    let aad_p = kat::aad_payload(FORMAT_MAX, RESERVED_KEY_ID, item_id)?;
    let wrapped = kat::xchacha20poly1305_seal(&kw, &wrap_nonce, &aad_w, &cek)?;
    let padded = kat::pad_payload(json_s.as_bytes());
    let ct = kat::xchacha20poly1305_seal(&cek, &payload_nonce, &aad_p, &padded)?;
    let mut env = Vec::new();
    env.extend_from_slice(&FORMAT_MAX.to_be_bytes());
    env.extend_from_slice(&RESERVED_KEY_ID.to_be_bytes());
    env.extend_from_slice(uuid::Uuid::parse_str(item_id)?.as_bytes());
    env.extend_from_slice(&wrap_nonce);
    env.extend_from_slice(&wrapped);
    env.extend_from_slice(&payload_nonce);
    env.extend_from_slice(&ct);
    let header = tomi_core::read_envelope_header(&env)?;
    check(header.key_epoch == RESERVED_KEY_ID, "reserved header")?;
    let inputs = json!({
        "format": FORMAT_MAX, "key_epoch": RESERVED_KEY_ID, "item_id": item_id,
        "key": h(key), "cek": h(&cek), "wrap_nonce": h(&wrap_nonce),
        "payload_nonce": h(&payload_nonce), "payload_json": json_s,
    });
    Ok((inputs, env))
}

fn reservation_vectors(a: &Dev, b: &Dev, c: &Dev, k1: &SpaceKey, k2: &SpaceKey) -> R<Value> {
    let a_id = a.keys.device_id();
    let b_id = b.keys.device_id();
    let c_id = c.keys.device_id();

    // -- payload: `audience` is ignored by a v1 reader, whatever its value (§5.8.1).
    let pid = "4a4b4c4d-4e4f-4051-8253-545556575859";
    let base = |extra: &str| {
        format!(r#"{{"id":"{pid}","source_device":"{a_id}","created_at":{T0}{extra}}}"#)
    };
    let case = |name: &str, desc: &str, extra: &str, equivalent_extra: &str| -> R<Value> {
        let json_s = base(extra);
        let equivalent = base(equivalent_extra);
        let got = kat::parse_payload(json_s.as_bytes(), pid)?;
        let want = kat::parse_payload(equivalent.as_bytes(), pid)?;
        check(got == want, name)?;
        Ok(json!({
            "name": name, "description": desc, "expected_item_id": pid,
            "json": json_s, "json_hex": h(json_s.as_bytes()),
            "equivalent_json": equivalent, "equivalent_json_hex": h(equivalent.as_bytes()),
            "expected_item": kat::item_to_value(&got),
        }))
    };
    let member = "0f1e2d3c4b5a69788796a5b4c3d2e1f0";
    let payload = vec![
        case(
            "audience_one_device",
            "audience with a recipient of type device: ignored, the item is broadcast to the whole space as without audience.",
            &format!(r#","text":{{"plain":"x"}},"audience":{{"to":[{{"type":"device","id":"{b_id}"}}]}}"#),
            r#","text":{"plain":"x"}"#,
        )?,
        case(
            "audience_several_recipients",
            "Several recipients (device, reserved member, unknown type) and unknown fields in audience and in an entry: everything is ignored.",
            &format!(
                r#","audience":{{"to":[{{"type":"device","id":"{b_id}"}},{{"type":"device","id":"{c_id}"}},{{"type":"member","id":"{member}"}},{{"type":"group","id":"g1","role":"x"}}],"mode":"only"}}"#
            ),
            "",
        )?,
        case(
            "audience_secret",
            "Secret with a title and audience: the secret flag and the title are read as without audience (audience changes neither masking nor search).",
            &format!(
                r#","secret":true,"title":"Code Wi-Fi","text":{{"plain":"hunter2"}},"audience":{{"to":[{{"type":"device","id":"{b_id}"}}]}}"#
            ),
            r#","secret":true,"title":"Code Wi-Fi","text":{"plain":"hunter2"}"#,
        )?,
        case(
            "audience_null",
            "audience null = absent = tout l'espace.",
            r#","audience":null"#,
            "",
        )?,
        case(
            "audience_empty_list",
            "audience with an empty to list: ignored by a v1 reader (and treated as absent by any future version).",
            r#","audience":{"to":[]}"#,
            "",
        )?,
        case(
            "audience_unexpected_type",
            "audience of an unexpected type (string): a v1 reader does not validate it and does not fail (no malformed_payload).",
            r#","audience":"everyone""#,
            "",
        )?,
    ];

    // -- full envelope carrying `audience`, under the space key of epoch 1.
    let env_id = "7a7b7c7d-7e7f-4081-8283-848586878889";
    let env_json = format!(
        r#"{{"id":"{env_id}","source_device":"{a_id}","created_at":{T0},"text":{{"plain":"Pour le PC"}},"audience":{{"to":[{{"type":"device","id":"{b_id}"}}]}}}}"#
    );
    let env_equivalent = format!(
        r#"{{"id":"{env_id}","source_device":"{a_id}","created_at":{T0},"text":{{"plain":"Pour le PC"}}}}"#
    );
    let mut env_vector = envelope_vector(
        "audience_in_envelope",
        "Complete envelope (§5) whose payload carries audience. It opens under the space key like any other: audience has no cryptographic effect, all members decrypt it; expected_item = the item of equivalent_payload_json.",
        k1,
        env_id,
        &seq(0xb0, 32),
        &seq(0xd0, 24),
        &seq(0xe8, 24),
        &env_json,
    )?;
    let equivalent_item = kat::parse_payload(env_equivalent.as_bytes(), env_id)?;
    check(
        env_vector["expected_item"] == kat::item_to_value(&equivalent_item),
        "audience envelope equivalence",
    )?;
    env_vector["equivalent_payload_json"] = json!(env_equivalent);

    // -- reserved key ids (§5.8.2): never a space key; received -> KeyPending.
    let ring_1 = SpaceKeyRing::new(k1.clone());
    let mut ring_12 = SpaceKeyRing::new(k1.clone());
    let rotation_seq = 100u64;
    ring_12.add_rotation_key(k2.clone(), rotation_seq, T0 as u64)?;
    let ring_value = |with_rotation: bool| {
        let mut keys = vec![json!({"epoch": 1, "key": h(&k1.to_bytes())})];
        let mut rotations = Vec::new();
        if with_rotation {
            keys.push(json!({"epoch": 2, "key": h(&k2.to_bytes())}));
            rotations.push(json!({"from_epoch": 1, "rotation_seq": rotation_seq}));
        }
        json!({"keys": keys, "rotations": rotations})
    };
    let group_key = seq(0x40, 32);
    let reserved_id = "5a5b5c5d-5e5f-4061-8263-646566676869";
    let reserved_json = format!(
        r#"{{"id":"{reserved_id}","source_device":"{a_id}","created_at":{T0},"text":{{"plain":"x"}},"audience":{{"to":[{{"type":"member","id":"{member}"}}]}}}}"#
    );
    let (reserved_inputs, reserved_env) =
        reserved_item_envelope(&group_key, reserved_id, &reserved_json)?;
    let mut items = Vec::new();
    for (name, desc, ring, with_rotation, item_seq) in [
        (
            "reserved_key_id_item",
            "Item whose header announces a reserved key_epoch (0x80000001): the v1 reader does not open it, keeps it raw and classifies it KEY_PENDING, never deleted.",
            &ring_1,
            false,
            10u64,
        ),
        (
            "reserved_key_id_item_after_rotation",
            "Same item after a 1 -> 2 rotation of lower seq: still KEY_PENDING (a reserved value is never a superseded epoch, hence never UNREADABLE_SUSPECT_EPOCH).",
            &ring_12,
            true,
            150u64,
        ),
    ] {
        let got = ring.open_received(&reserved_env, reserved_id, item_seq);
        check(
            got == tomi_core::ReceivedItem::Unreadable(UnreadableReason::KeyPending),
            name,
        )?;
        items.push(json!({
            "name": name, "description": desc, "inputs": reserved_inputs,
            "envelope": h(&reserved_env), "announced_item_id": reserved_id,
            "item_seq": item_seq, "ring": ring_value(with_rotation),
            "expected_reason": UnreadableReason::KeyPending.code(),
        }));
    }

    let event_id = "e0000000-0000-4000-8000-0000000000f1";
    let state_nonce = seq(0x30, 24);
    let state_inner = kat::pad_payload(b"tomi/v1/reserved-example");
    let state_key = kat::hkdf_sha256(&[], &group_key, b"tomi/v1/hkdf/item-state", 32)?;
    let state_aad = kat::aad_item_state(FORMAT_MAX, RESERVED_KEY_ID, event_id)?;
    let state_ct = kat::xchacha20poly1305_seal(&state_key, &state_nonce, &state_aad, &state_inner)?;
    let mut state_env = Vec::new();
    state_env.extend_from_slice(&FORMAT_MAX.to_be_bytes());
    state_env.extend_from_slice(&RESERVED_KEY_ID.to_be_bytes());
    state_env.extend_from_slice(uuid::Uuid::parse_str(event_id)?.as_bytes());
    state_env.extend_from_slice(&state_nonce);
    state_env.extend_from_slice(&state_ct);
    check(
        state_env.len() == ITEM_STATE_ENVELOPE_LEN,
        "reserved state length",
    )?;
    let state_seq = 160u64;
    check(
        matches!(
            ring_12.open_received_state(&state_env, event_id, state_seq),
            ReceivedItemState::Unreadable(UnreadableReason::KeyPending)
        ),
        "reserved state",
    )?;
    let item_states = vec![json!({
        "name": "reserved_key_id_item_state",
        "description": "Item state event (320 bytes) whose header announces a reserved key_epoch: kept raw (KeyPending), never opened or applied.",
        "inputs": {
            "format": FORMAT_MAX, "key_epoch": RESERVED_KEY_ID, "event_id": event_id,
            "key": h(&group_key), "nonce": h(&state_nonce), "padded_content": h(&state_inner),
        },
        "envelope": h(&state_env), "announced_event_id": event_id, "seq": state_seq,
        "ring": ring_value(true), "expected_reason": UnreadableReason::KeyPending.code(),
    })];

    // Signed statements that would put a space key in the reserved range.
    let space16 = *uuid::Uuid::parse_str(SPACE_ID)?.as_bytes();
    let a_pub = a.public();
    let reserved_epoch = 0x8000_0000u32;
    let mut rot_tbs = b"tomi/v1/sig/key-rotation\0".to_vec();
    rot_tbs.extend_from_slice(&space16);
    rot_tbs.extend_from_slice(&reserved_epoch.to_be_bytes());
    rot_tbs.extend_from_slice(&(T0 as u64).to_be_bytes());
    rot_tbs.extend_from_slice(&a_pub.ed25519);
    rot_tbs.extend_from_slice(&0u32.to_be_bytes());
    rot_tbs.extend_from_slice(&0u32.to_be_bytes());
    let mut list_tbs = b"tomi/v1/sig/member-list\0".to_vec();
    list_tbs.extend_from_slice(&space16);
    list_tbs.extend_from_slice(&reserved_epoch.to_be_bytes());
    list_tbs.extend_from_slice(&(T0 as u64).to_be_bytes());
    list_tbs.extend_from_slice(&a_pub.ed25519);
    list_tbs.extend_from_slice(&1u32.to_be_bytes());
    list_tbs.extend_from_slice(&a_pub.ed25519);
    list_tbs.extend_from_slice(&a_pub.x25519);
    let mut statements = Vec::new();
    for (name, kind, tbs) in [
        ("key_rotation_to_reserved_epoch", "key_rotation", rot_tbs),
        ("member_list_reserved_epoch", "member_list", list_tbs),
    ] {
        let sig = kat::ed25519_sign(&a.ed_seed, &tbs)?;
        kat::ed25519_verify(&a_pub.ed25519, &tbs, &sig)?;
        let mut wire = tbs.clone();
        wire.extend_from_slice(&sig);
        let err = match kind {
            "key_rotation" => tomi_core::KeyRotation::from_bytes(&wire).map(|_| ()),
            _ => tomi_core::MemberList::from_bytes(&wire).map(|_| ()),
        };
        check(
            err.as_ref().err().map(|e| e.code()) == Some("malformed_statement"),
            name,
        )?;
        statements.push(json!({
            "name": name, "kind": kind,
            "description": "Statement correctly signed by A whose epoch (0x80000000) is in the reserved range: refused at decoding, before any signature verification (malformed_statement).",
            "key_epoch": reserved_epoch, "issued_at_ms": T0, "signer": "A",
            "tbs": h(&tbs), "wire": h(&wire), "expected_error": "malformed_statement",
        }));
    }

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Format 1 reservations for future multi-recipient sharing (§5.8). payload: read json_hex as in payload-json.json; the result MUST be identical to that of equivalent_json_hex (the same item without audience). envelope: as item-text.json, then compare to equivalent_payload_json. reserved_key_epoch: build the SpaceKeyRing from ring (keys, then rotations applied at seq rotation_seq), open envelope (items: open_received with announced_item_id and item_seq; item_states: open_received_state with announced_event_id and seq) and obtain expected_reason; statements: decode wire and obtain expected_error. No existing file is modified by these reservations.",
        "payload": payload,
        "envelope": [env_vector],
        "reserved_key_epoch": {
            "space_key_epoch_max": tomi_core::SPACE_KEY_EPOCH_MAX,
            "reserved_min": tomi_core::SPACE_KEY_EPOCH_MAX as u64 + 1,
            "reserved_max": u32::MAX,
            "items": items,
            "item_states": item_states,
            "statements": statements,
        },
    }))
}
